@property --mdd-cutline-fade-top { syntax: "<number>"; inherits: false; initial-value: 0; }
@property --mdd-cutline-fade-end { syntax: "<number>"; inherits: false; initial-value: 1; }

.mdd-cutline {
  --mdd-cutline-paper: oklch(0.983 0.008 85);
  --mdd-cutline-ink: oklch(0.25 0.025 265);
  --mdd-cutline-accent: oklch(0.63 0.19 33);
  --mdd-cutline-radius: 10px;
  --mdd-cutline-line: color-mix(in oklch, var(--mdd-cutline-ink) 11%, transparent);
  --mdd-cutline-muted: color-mix(in oklch, var(--mdd-cutline-ink) 56%, var(--mdd-cutline-paper));
  --mdd-cutline-tint: color-mix(in oklch, var(--mdd-cutline-ink) 3.5%, var(--mdd-cutline-paper));
  --mdd-cutline-ease: cubic-bezier(.2, .8, .2, 1);
  --mdd-cutline-spring: linear(0, 0.046, 0.156, 0.297, 0.446, 0.588, 0.712, 0.815, 0.896, 0.957, 0.998, 1.025, 1.039, 1.045, 1.045, 1.041, 1.035, 1.029, 1.022, 1.016, 1.011, 1.006, 1.003, 1.001, 0.999, 0.998, 1);
  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head" "ruler" "list" "foot";
  gap: 12px;
  inline-size: 100%;
  max-inline-size: 440px;
  box-sizing: border-box;
  padding: 18px 16px 14px;
  border-radius: 16px;
  background: var(--mdd-cutline-paper);
  color: var(--mdd-cutline-ink);
  font: 400 13px/1.35 system-ui, -apple-system, "Segoe UI", sans-serif;
  box-shadow: 0 0 0 1px var(--mdd-cutline-line), 0 18px 40px -22px oklch(0.2 0.03 265 / 0.5);
  accent-color: var(--mdd-cutline-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(button) { font: inherit; color: inherit; }
  & :focus-visible { outline: 2px solid var(--mdd-cutline-accent); outline-offset: 2px; }
}

.mdd-cutline-head {
  grid-area: head;
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-areas: "eyebrow lock" "title stat" "sub sub";
  align-items: end;
  row-gap: 2px;
  column-gap: 12px;
}
.mdd-cutline-eyebrow {
  grid-area: eyebrow;
  margin: 0;
  font-size: 10.5px;
  font-weight: 650;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--mdd-cutline-muted);
}
.mdd-cutline-title {
  grid-area: title;
  margin: 0;
  font-size: clamp(18px, 6cqi, 23px);
  font-weight: 680;
  letter-spacing: -0.02em;
  line-height: 1.1;
  text-wrap: balance;
}
.mdd-cutline-stat {
  grid-area: stat;
  margin: 0;
  font-family: ui-monospace, Menlo, monospace;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
  & strong { display: inline-block; font-size: clamp(18px, 6cqi, 23px); font-weight: 650; letter-spacing: -0.03em; }
  & span { font-size: 12px; color: var(--mdd-cutline-muted); margin-inline-start: 2px; }
}
.mdd-cutline-sub {
  grid-area: sub;
  margin: 4px 0 0;
  display: flex;
  flex-wrap: wrap;
  gap: 2px 0;
  font-size: 11.5px;
  color: var(--mdd-cutline-muted);
  text-wrap: pretty;
  & span + span::before { content: "·"; margin-inline: 6px; opacity: 0.6; }
  & [data-next] { color: color-mix(in oklch, var(--mdd-cutline-accent) 80%, var(--mdd-cutline-ink)); }
}
.mdd-cutline-lock {
  grid-area: lock;
  align-self: start;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 9px 4px 7px;
  border: 1px solid var(--mdd-cutline-line);
  border-radius: 999px;
  background: transparent;
  font-size: 11.5px;
  font-weight: 560;
  color: var(--mdd-cutline-muted);
  cursor: pointer;
  transition: background-color .2s, color .2s, border-color .2s;
  & svg { inline-size: 14px; block-size: 14px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; }
  & .mdd-cutline-shackle { transform-origin: 10.5px 7px; transition: transform .3s var(--mdd-cutline-ease); transform: rotate(28deg) translateY(-0.6px); }
  &:hover { background: var(--mdd-cutline-tint); color: var(--mdd-cutline-ink); }
  &[aria-pressed="true"] {
    background: var(--mdd-cutline-ink);
    border-color: var(--mdd-cutline-ink);
    color: var(--mdd-cutline-paper);
    & .mdd-cutline-shackle { transform: none; }
  }
}

.mdd-cutline-ruler { grid-area: ruler; display: grid; gap: 5px; }
.mdd-cutline-track {
  container-type: inline-size;
  position: relative;
  block-size: 12px;
  border-radius: 4px;
  background: repeating-linear-gradient(90deg, var(--mdd-cutline-line) 0 1px, transparent 1px calc(100% / 31));
}
.mdd-cutline-seg {
  position: absolute;
  inset-block: 0;
  inset-inline-start: 0;
  inline-size: max(2px, calc(var(--w) * 1cqi - 2px));
  transform: translateX(calc(var(--x) * 1cqi));
  border-radius: 3px;
  background: color-mix(in oklch, var(--mdd-cutline-ink) 86%, var(--mdd-cutline-paper));
  transition: transform .5s var(--mdd-cutline-spring), background-color .25s, box-shadow .25s;
  &[data-alt] { background: color-mix(in oklch, var(--mdd-cutline-ink) 62%, var(--mdd-cutline-paper)); }
  &[data-out] {
    background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--mdd-cutline-ink) 32%, transparent) 0 1.5px, transparent 1.5px 4.5px);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mdd-cutline-ink) 24%, transparent);
  }
  &[data-hot] { background: var(--mdd-cutline-accent); box-shadow: 0 0 0 2px color-mix(in oklch, var(--mdd-cutline-accent) 30%, transparent); }
  &[data-hot][data-out] { background: repeating-linear-gradient(-45deg, var(--mdd-cutline-accent) 0 1.5px, transparent 1.5px 4.5px); box-shadow: inset 0 0 0 1.5px var(--mdd-cutline-accent); }
}
.mdd-cutline-cap {
  position: absolute;
  inset-block: -4px;
  inset-inline-start: calc(var(--cap) * 1cqi - 1px);
  inline-size: 2px;
  border-radius: 2px;
  background: var(--mdd-cutline-accent);
  z-index: 2;
}
.mdd-cutline-ticks {
  position: relative;
  block-size: 12px;
  font: 500 9.5px/12px ui-monospace, Menlo, monospace;
  font-variant-numeric: tabular-nums;
  color: var(--mdd-cutline-muted);
  & span { position: absolute; inset-inline-start: calc(var(--x) * 1%); translate: -50% 0; white-space: nowrap; }
  & span:first-child { translate: 0 0; }
  & span:last-child { translate: -100% 0; }
  & [data-cap] { color: var(--mdd-cutline-accent); font-weight: 700; }
}

.mdd-cutline-list {
  grid-area: list;
  position: relative;
  margin: 0 -9px;
  padding: 4px 9px;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-block-size: 322px;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--mdd-cutline-ink) 22%, transparent) transparent;
  --mdd-cutline-fade-top: 0;
  --mdd-cutline-fade-end: 1;
  mask-image: linear-gradient(to bottom, transparent 0, #000 calc(var(--mdd-cutline-fade-top) * 18px), #000 calc(100% - var(--mdd-cutline-fade-end) * 18px), transparent 100%);
}
@supports (animation-timeline: scroll()) {
  .mdd-cutline-list {
    animation: mdd-cutline-fade linear both;
    animation-timeline: scroll(self);
  }
}
@keyframes mdd-cutline-fade {
  0% { --mdd-cutline-fade-top: 0; --mdd-cutline-fade-end: 1; }
  10% { --mdd-cutline-fade-top: 1; }
  90% { --mdd-cutline-fade-end: 1; }
  100% { --mdd-cutline-fade-top: 1; --mdd-cutline-fade-end: 0; }
}

.mdd-cutline-row {
  flex: none;
  position: relative;
  display: grid;
  grid-template-columns: 26px 20px minmax(0, 1fr) auto;
  grid-template-areas: "grip rank name eff" "grip rank meta eff";
  align-items: center;
  column-gap: 8px;
  min-block-size: 46px;
  padding: 5px 12px 5px 2px;
  border-radius: var(--mdd-cutline-radius);
  background: var(--mdd-cutline-tint);
  box-shadow: inset 0 0 0 1px var(--mdd-cutline-line);
  transition: transform .28s var(--mdd-cutline-ease), scale .22s var(--mdd-cutline-ease), rotate .22s var(--mdd-cutline-ease), background-color .2s, box-shadow .2s;
  &:hover { background: color-mix(in oklch, var(--mdd-cutline-ink) 6%, var(--mdd-cutline-paper)); }
  &[data-out] {
    background: transparent;
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mdd-cutline-ink) 9%, transparent);
    & .mdd-cutline-name { color: var(--mdd-cutline-muted); }
    & .mdd-cutline-eff b { color: var(--mdd-cutline-muted); }
  }
  &[data-lifted] {
    z-index: 3;
    scale: 1.015;
    rotate: -0.5deg;
    background: var(--mdd-cutline-paper);
    box-shadow: 0 0 0 1.5px var(--mdd-cutline-accent), 0 16px 28px -14px oklch(0.2 0.04 265 / 0.55), 0 2px 6px oklch(0.2 0.04 265 / 0.12);
    & .mdd-cutline-name { color: var(--mdd-cutline-ink); }
    & .mdd-cutline-grip { cursor: grabbing; color: var(--mdd-cutline-accent); }
  }
}
.mdd-cutline-list[data-pointer] .mdd-cutline-row[data-lifted] { transition: scale .22s var(--mdd-cutline-ease), rotate .22s var(--mdd-cutline-ease), box-shadow .2s; }
.mdd-cutline-list[data-dragging] { cursor: grabbing; & .mdd-cutline-row { will-change: transform; } }
.mdd-cutline-grip {
  grid-area: grip;
  align-self: stretch;
  display: grid;
  place-items: center;
  margin: -2px 0;
  padding: 0;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: color-mix(in oklch, var(--mdd-cutline-ink) 38%, transparent);
  cursor: grab;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  transition: color .15s, background-color .15s;
  & svg { inline-size: 16px; block-size: 16px; fill: currentColor; }
  &:hover { color: var(--mdd-cutline-ink); background: color-mix(in oklch, var(--mdd-cutline-ink) 6%, transparent); }
  &:focus-visible { outline-offset: -2px; }
}
.mdd-cutline-rank {
  grid-area: rank;
  font: 600 11px/1 ui-monospace, Menlo, monospace;
  font-variant-numeric: tabular-nums;
  color: var(--mdd-cutline-muted);
  text-align: end;
}
.mdd-cutline-name {
  grid-area: name;
  font-size: 13.5px;
  font-weight: 590;
  letter-spacing: -0.005em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  transition: color .2s;
}
.mdd-cutline-meta {
  grid-area: meta;
  display: flex;
  align-items: center;
  gap: 6px;
  min-inline-size: 0;
  font-size: 11px;
  color: var(--mdd-cutline-muted);
  white-space: nowrap;
  overflow: hidden;
  & > span:first-child { overflow: hidden; text-overflow: ellipsis; }
}
.mdd-cutline-fits {
  display: none;
  flex: none;
  padding: 1px 6px;
  border-radius: 999px;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: color-mix(in oklch, oklch(0.5 0.12 155) 90%, var(--mdd-cutline-ink));
  background: color-mix(in oklch, oklch(0.62 0.13 155) 16%, transparent);
}
.mdd-cutline-row[data-fits] .mdd-cutline-fits { display: inline-block; }
.mdd-cutline-eff {
  grid-area: eff;
  font-family: ui-monospace, Menlo, monospace;
  font-variant-numeric: tabular-nums;
  font-size: 10.5px;
  color: var(--mdd-cutline-muted);
  white-space: nowrap;
  & b { font-size: 15px; font-weight: 650; color: var(--mdd-cutline-ink); margin-inline-end: 2px; }
}

.mdd-cutline-cut {
  flex: none;
  position: relative;
  display: flex;
  justify-content: space-between;
  align-items: center;
  block-size: 24px;
  padding-inline: 8px;
  font-size: 9.5px;
  font-weight: 750;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--mdd-cutline-accent);
  transition: transform .28s var(--mdd-cutline-ease);
  &::before {
    content: "";
    position: absolute;
    inset-inline: 0;
    inset-block-start: 50%;
    border-block-start: 1.5px dashed currentColor;
  }
  & span { position: relative; padding-inline: 6px; background: var(--mdd-cutline-paper); border-radius: 4px; }
}

.mdd-cutline-foot {
  grid-area: foot;
  display: grid;
  min-block-size: 30px;
  align-items: center;
  & > * { grid-area: 1 / 1; margin: 0; }
}
.mdd-cutline-hint {
  font-size: 11px;
  color: var(--mdd-cutline-muted);
  text-wrap: pretty;
  transition: opacity .2s;
  & kbd {
    display: inline-block;
    min-inline-size: 18px;
    margin-inline: 1px;
    padding: 1px 4px;
    border-radius: 4px;
    font: 600 10px/1.4 ui-monospace, Menlo, monospace;
    text-align: center;
    background: var(--mdd-cutline-paper);
    box-shadow: inset 0 0 0 1px var(--mdd-cutline-line), 0 1px 0 var(--mdd-cutline-line);
  }
}
.mdd-cutline-foot:has(.mdd-cutline-toast:not([hidden])) .mdd-cutline-hint { opacity: 0; pointer-events: none; }
.mdd-cutline-toast {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 6px 6px 6px 12px;
  border-radius: 9px;
  background: var(--mdd-cutline-ink);
  color: var(--mdd-cutline-paper);
  font-size: 11.5px;
  transition: opacity .22s, translate .4s var(--mdd-cutline-spring), display .4s allow-discrete;
  & [data-msg] { min-inline-size: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  &[hidden] { display: none; opacity: 0; translate: 0 6px; }
  @starting-style { opacity: 0; translate: 0 8px; }
}
.mdd-cutline-undo {
  flex: none;
  padding: 3px 10px;
  border: 0;
  border-radius: 6px;
  background: color-mix(in oklch, var(--mdd-cutline-paper) 14%, transparent);
  color: var(--mdd-cutline-paper);
  font-weight: 650;
  cursor: pointer;
  &:hover { background: color-mix(in oklch, var(--mdd-cutline-paper) 24%, transparent); }
}
.mdd-cutline-sr { position: absolute; inline-size: 1px; block-size: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; margin: 0; }

.mdd-cutline[data-locked] {
  & .mdd-cutline-grip { cursor: not-allowed; color: color-mix(in oklch, var(--mdd-cutline-ink) 22%, transparent); }
  & .mdd-cutline-grip:hover { background: transparent; }
  & .mdd-cutline-row:hover { background: var(--mdd-cutline-tint); }
  & .mdd-cutline-row[data-out]:hover { background: transparent; }
}

@container (width < 340px) {
  .mdd-cutline-head { grid-template-areas: "eyebrow eyebrow" "title lock" "stat stat" "sub sub"; }
  .mdd-cutline-lock span { display: none; }
  .mdd-cutline-lock { padding: 5px; }
  .mdd-cutline-stat { margin-block-start: 6px; }
  .mdd-cutline-sub [data-next] { display: none; }
  .mdd-cutline-row { grid-template-columns: 24px 16px minmax(0, 1fr) auto; column-gap: 6px; }
  .mdd-cutline-name { white-space: normal; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; line-height: 1.2; font-size: 13px; }
  .mdd-cutline-owner { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .mdd-cutline-row, .mdd-cutline-cut { transition: background-color .2s, box-shadow .2s; }
  .mdd-cutline-row[data-lifted] { scale: 1; rotate: 0deg; }
  .mdd-cutline-seg { transition: background-color .2s; }
  .mdd-cutline-lock .mdd-cutline-shackle { transition: none; }
  .mdd-cutline-toast { transition: opacity .2s, display .2s allow-discrete; translate: none; &[hidden] { translate: none; } @starting-style { translate: none; } }
}

js:
const CAP = 24;
const DATA = [
  { id: "sso", t: "SSO for workspace admins", c: "Security", o: "Priya Natarajan", e: 6 },
  { id: "offline", t: "Offline drafts on mobile", c: "Mobile", o: "Tomás Ferreira", e: 5 },
  { id: "csv", t: "Bulk export to CSV", c: "Data", o: "Hana Kobayashi", e: 2 },
  { id: "alerts", t: "Usage-based billing alerts", c: "Billing", o: "Dele Adeyemi", e: 4 },
  { id: "audit", t: "Audit log retention controls", c: "Security", o: "Priya Natarajan", e: 3 },
  { id: "threads", t: "Comment threads on charts", c: "Collaboration", o: "Inès Moreau", e: 5 },
  { id: "cold", t: "Cold start under 1.2 s", c: "Performance", o: "Jonah Pruitt", e: 4 },
  { id: "embeds", t: "Dark mode for embeds", c: "Design", o: "Saskia Vos", e: 2 }
];
const TOTAL = DATA.reduce((s, d) => s + d.e, 0);
const SCALE = Math.max(TOTAL, CAP);
const SPRING = "linear(0, 0.046, 0.156, 0.297, 0.446, 0.588, 0.712, 0.815, 0.896, 0.957, 0.998, 1.025, 1.039, 1.045, 1.045, 1.041, 1.035, 1.029, 1.022, 1.016, 1.011, 1.006, 1.003, 1.001, 0.999, 0.998, 1)";
const GRIP = '<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="6" cy="3.5" r="1.25"/><circle cx="10" cy="3.5" r="1.25"/><circle cx="6" cy="8" r="1.25"/><circle cx="10" cy="8" r="1.25"/><circle cx="6" cy="12.5" r="1.25"/><circle cx="10" cy="12.5" r="1.25"/></svg>';

const $ = (s) => root.querySelector(s);
const list = $(".mdd-cutline-list");
const track = $(".mdd-cutline-track");
const ticks = $(".mdd-cutline-ticks");
const live = $(".mdd-cutline-sr");
const lockBtn = $(".mdd-cutline-lock");
const toast = $(".mdd-cutline-toast");
const help = $(".mdd-cutline-help");
const reduce = () => matchMedia("(prefers-reduced-motion: reduce)").matches;
const byId = Object.fromEntries(DATA.map((d) => [d.id, d]));
const uid = "mdd-cutline-" + Math.random().toString(36).slice(2, 8);
help.id = uid + "-help";

let order = DATA.map((d) => d.id);
let locked = false;
let drag = null;
let undoOrder = null;
let toastTimer = 0;

/* ---------- build ---------- */
const rows = {};
const segs = {};
for (const d of DATA) {
  const li = document.createElement("li");
  li.className = "mdd-cutline-row";
  li.dataset.id = d.id;
  li.innerHTML =
    '<button type="button" class="mdd-cutline-grip" tabindex="-1" aria-describedby="' + help.id + '">' + GRIP + "</button>" +
    '<span class="mdd-cutline-rank"></span><span class="mdd-cutline-name"></span>' +
    '<span class="mdd-cutline-meta"><span><span class="mdd-cutline-cat"></span><span class="mdd-cutline-owner"></span></span><span class="mdd-cutline-fits">fits</span></span>' +
    '<span class="mdd-cutline-eff"><b>' + d.e + "</b>wk</span>";
  li.querySelector(".mdd-cutline-name").textContent = d.t;
  li.querySelector(".mdd-cutline-cat").textContent = d.c;
  li.querySelector(".mdd-cutline-owner").textContent = " · " + d.o;
  rows[d.id] = li;
  const s = document.createElement("i");
  s.className = "mdd-cutline-seg";
  s.style.setProperty("--w", (d.e / SCALE) * 100);
  track.append(s);
  segs[d.id] = s;
}
const cut = document.createElement("li");
cut.className = "mdd-cutline-cut";
cut.setAttribute("role", "separator");
cut.setAttribute("aria-label", "Capacity line, " + CAP + " weeks. Items below slip to Q4.");
cut.innerHTML = "<span>Q3 capacity · " + CAP + " wk</span><span>Q4 ↓</span>";
track.style.setProperty("--cap", (CAP / SCALE) * 100);
[0, 8, 16, CAP, TOTAL].forEach((v) => {
  const t = document.createElement("span");
  t.style.setProperty("--x", (v / SCALE) * 100);
  t.textContent = v === CAP ? CAP + " cap" : String(v);
  if (v === CAP) t.dataset.cap = "";
  ticks.append(t);
});
rows[order[0]].querySelector(".mdd-cutline-grip").tabIndex = 0;

/* ---------- model ---------- */
function split(ord) {
  let s = 0, k = 0;
  for (const id of ord) { if (s + byId[id].e > CAP) break; s += byId[id].e; k++; }
  return { k, s };
}
function seqFor(ord) {
  const { k } = split(ord);
  return [...ord.slice(0, k).map((id) => rows[id]), cut, ...ord.slice(k).map((id) => rows[id])];
}
function place(el, before) {
  if (list.moveBefore && el.parentNode === list) list.moveBefore(el, before);
  else list.insertBefore(el, before);
}

let lastCommitted = null;
function paint(ord, hot) {
  const { k, s } = split(ord);
  const free = CAP - s;
  ord.forEach((id, i) => {
    const li = rows[id];
    const out = i >= k;
    li.toggleAttribute("data-out", out);
    li.toggleAttribute("data-fits", out && byId[id].e <= free);
    li.querySelector(".mdd-cutline-rank").textContent = String(i + 1).padStart(2, "0");
  });
  let x = 0;
  ord.forEach((id, i) => {
    const sg = segs[id];
    sg.style.setProperty("--x", (x / SCALE) * 100);
    sg.toggleAttribute("data-out", i >= k);
    sg.toggleAttribute("data-alt", i % 2 === 1);
    sg.toggleAttribute("data-hot", id === hot);
