  if (cancel) { say("Cancelled. " + byId[d.id].t + " back at rank " + (d.from + 1) + "."); return; }
  if (changed) {
    undoOrder = d.base;
    const { s } = split(order);
    say("Dropped. " + where(order, d.id) + ". Q3 commits " + s + " of " + CAP + " weeks.");
    showToast("Moved “" + byId[d.id].t + "” to rank " + (order.indexOf(d.id) + 1));
