css:
@property --mdd-outline-x { syntax: "<length>"; inherits: true; initial-value: 0px; }
@property --mdd-outline-dwell { syntax: "<percentage>"; inherits: false; initial-value: 0%; }

.mdd-outline {
  --mdd-outline-bg: oklch(0.205 0.01 70);
  --mdd-outline-ink: oklch(0.93 0.012 85);
  --mdd-outline-accent: oklch(0.82 0.15 78);
  --mdd-outline-indent: 16px;
  --mdd-outline-line: color-mix(in oklch, var(--mdd-outline-ink) 9%, transparent);
  --mdd-outline-muted: color-mix(in oklch, var(--mdd-outline-ink) 52%, var(--mdd-outline-bg));
  --mdd-outline-raise: color-mix(in oklch, var(--mdd-outline-ink) 5%, var(--mdd-outline-bg));
  --mdd-outline-glow: color-mix(in oklch, var(--mdd-outline-accent) 14%, transparent);
  --mdd-outline-ease: cubic-bezier(.22, .8, .24, 1);
  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-areas: "head" "tree" "foot";
  inline-size: 100%;
  max-inline-size: 400px;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--mdd-outline-bg);
  color: var(--mdd-outline-ink);
  font: 400 13px/1.3 system-ui, -apple-system, "Segoe UI", sans-serif;
  box-shadow: inset 0 0 0 1px var(--mdd-outline-line), 0 20px 40px -24px oklch(0 0 0 / 0.7);
  overflow: hidden;
  user-select: none;
  -webkit-user-select: none;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
}

.mdd-outline-head {
  grid-area: head;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 14px 10px;
  border-block-end: 1px solid var(--mdd-outline-line);
}
.mdd-outline-mark {
  display: grid;
  place-items: center;
  inline-size: 28px;
  block-size: 28px;
  border-radius: 8px;
  color: var(--mdd-outline-bg);
  background: var(--mdd-outline-accent);
  & svg { inline-size: 15px; block-size: 15px; fill: currentColor; stroke-width: 1.2; }
}
.mdd-outline-space {
  display: grid;
  font-size: 14px;
  font-weight: 650;
  letter-spacing: -0.01em;
  & small {
    font-size: 11px;
    font-weight: 450;
    letter-spacing: 0;
    color: var(--mdd-outline-muted);
    font-variant-numeric: tabular-nums;
  }
}

.mdd-outline-scroll {
  grid-area: tree;
  position: relative;
  max-block-size: 330px;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 6px 6px 8px;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--mdd-outline-ink) 20%, transparent) transparent;
}
.mdd-outline-tree { list-style: none; margin: 0; padding: 0; position: relative; }

.mdd-outline-item {
  --d: 0;
  position: relative;
  display: grid;
  grid-template-columns: 16px 16px minmax(0, 1fr) auto 14px;
  align-items: center;
  column-gap: 6px;
  block-size: 30px;
  padding-inline: calc(6px + var(--d) * var(--mdd-outline-indent)) 8px;
  border-radius: 7px;
  color: color-mix(in oklch, var(--mdd-outline-ink) 82%, var(--mdd-outline-bg));
  background-image: repeating-linear-gradient(90deg, var(--mdd-outline-line) 0 1px, transparent 1px var(--mdd-outline-indent));
  background-size: calc(var(--d) * var(--mdd-outline-indent)) 100%;
  background-position: 13px 0;
  background-repeat: no-repeat;
  cursor: default;
  outline: none;
  transition: background-color .15s, color .15s, opacity .2s;
  &:hover { background-color: var(--mdd-outline-raise); color: var(--mdd-outline-ink); & .mdd-outline-grip { opacity: 1; } }
  &:focus-visible { box-shadow: inset 0 0 0 2px var(--mdd-outline-accent); }
  &[aria-selected="true"] {
    color: var(--mdd-outline-ink);
    background-color: color-mix(in oklch, var(--mdd-outline-accent) 13%, var(--mdd-outline-bg));
    & .mdd-outline-label { font-weight: 600; }
    & .mdd-outline-doc { color: var(--mdd-outline-accent); }
  }
  &[data-origin] {
    opacity: 0.38;
    background-color: transparent;
    outline: 1px dashed color-mix(in oklch, var(--mdd-outline-ink) 30%, transparent);
    outline-offset: -1px;
  }
  &[data-kbd] {
    opacity: 1;
    outline: 1.5px solid var(--mdd-outline-accent);
    background-color: var(--mdd-outline-glow);
  }
  &[data-target] {
    background-color: var(--mdd-outline-glow);
    color: var(--mdd-outline-ink);
    & .mdd-outline-doc { color: var(--mdd-outline-accent); }
  }
  &[data-dwell]::after {
    content: "";
    position: absolute;
    inset: auto 8px 3px calc(28px + var(--d) * var(--mdd-outline-indent));
    block-size: 2px;
    border-radius: 2px;
    background: linear-gradient(90deg, var(--mdd-outline-accent) var(--mdd-outline-dwell), transparent 0);
    animation: mdd-outline-dwell .65s linear forwards;
  }
}
@keyframes mdd-outline-dwell { to { --mdd-outline-dwell: 100%; } }

.mdd-outline-chev {
  display: grid;
  place-items: center;
  inline-size: 18px;
  block-size: 22px;
  margin-inline-start: -2px;
  border-radius: 5px;
  color: var(--mdd-outline-muted);
  cursor: pointer;
  & svg { inline-size: 12px; block-size: 12px; transition: rotate .25s var(--mdd-outline-ease); }
  &:hover { color: var(--mdd-outline-ink); background: color-mix(in oklch, var(--mdd-outline-ink) 8%, transparent); }
}
.mdd-outline-item[aria-expanded="true"] .mdd-outline-chev svg { rotate: 90deg; }
.mdd-outline-item:not([aria-expanded]) .mdd-outline-chev { visibility: hidden; }
.mdd-outline-doc { inline-size: 15px; block-size: 15px; color: var(--mdd-outline-muted); transition: color .15s; }
.mdd-outline-label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mdd-outline-n {
  min-inline-size: 18px;
  padding: 1px 5px;
  border-radius: 999px;
  font: 600 10px/1.4 ui-monospace, Menlo, monospace;
  font-variant-numeric: tabular-nums;
  text-align: center;
  color: var(--mdd-outline-muted);
  background: var(--mdd-outline-line);
}
.mdd-outline-item:not([aria-expanded="false"]) .mdd-outline-n { visibility: hidden; }
.mdd-outline-grip {
  opacity: 0;
  color: var(--mdd-outline-muted);
  cursor: grab;
  transition: opacity .15s;
  & svg { inline-size: 14px; block-size: 14px; fill: currentColor; stroke: none; }
}

.mdd-outline-line {
  position: absolute;
  inset-inline: 0 10px;
  inset-block-start: 0;
  block-size: 0;
  pointer-events: none;
  opacity: 0;
  transition: opacity .12s, translate .14s var(--mdd-outline-ease), --mdd-outline-x .16s var(--mdd-outline-ease);
  &::before {
    content: "";
    position: absolute;
    inset-inline: 0;
    inset-block-start: -1px;
    block-size: 2px;
    border-radius: 2px;
    background: var(--mdd-outline-accent);
    clip-path: inset(0 0 0 var(--mdd-outline-x));
    box-shadow: 0 0 10px var(--mdd-outline-accent);
  }
  & i {
    position: absolute;
    inset-block-start: -4px;
    inset-inline-start: 0;
    inline-size: 8px;
    block-size: 8px;
    border-radius: 50%;
    border: 2px solid var(--mdd-outline-accent);
    background: var(--mdd-outline-bg);
    translate: calc(var(--mdd-outline-x) - 4px) 0;
  }
}
.mdd-outline[data-dragging] .mdd-outline-line[data-on] { opacity: 1; }
.mdd-outline[data-dragging] { & .mdd-outline-item:hover { background-color: transparent; } & .mdd-outline-item:hover .mdd-outline-grip { opacity: 0; } cursor: grabbing; }
.mdd-outline[data-dragging] .mdd-outline-item[data-target] { background-color: var(--mdd-outline-glow); }

.mdd-outline-foot {
  grid-area: foot;
  display: grid;
  align-items: center;
  min-block-size: 38px;
  padding: 8px 14px 10px;
  border-block-start: 1px solid var(--mdd-outline-line);
  font-size: 11px;
  color: var(--mdd-outline-muted);
  & > p { grid-area: 1 / 1; margin: 0; transition: opacity .18s, translate .3s var(--mdd-outline-ease); }
  & kbd {
    display: inline-block;
    min-inline-size: 17px;
    padding: 0 4px;
    margin-inline: 1px;
    border-radius: 4px;
    font: 600 10px/1.6 ui-monospace, Menlo, monospace;
    text-align: center;
    color: var(--mdd-outline-ink);
    background: var(--mdd-outline-raise);
    box-shadow: inset 0 0 0 1px var(--mdd-outline-line);
  }
}
.mdd-outline-crumb {
  opacity: 0;
  translate: 0 6px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  & b { color: var(--mdd-outline-ink); font-weight: 600; }
  & span { color: var(--mdd-outline-accent); font-weight: 650; text-transform: uppercase; letter-spacing: 0.08em; font-size: 9.5px; margin-inline-end: 6px; }
  & i { font-style: normal; opacity: 0.55; margin-inline: 4px; }
}
.mdd-outline[data-dragging] {
  & .mdd-outline-crumb { opacity: 1; translate: 0 0; }
  & .mdd-outline-keys { opacity: 0; translate: 0 -6px; }
}

.mdd-outline-ghost {
  position: absolute;
  inset: 0 auto auto 0;
  z-index: 5;
  display: none;
  align-items: center;
  gap: 7px;
  max-inline-size: 230px;
  padding: 6px 10px 6px 8px;
  border-radius: 8px;
