  font: 400 13px/1.35 system-ui, -apple-system, "Segoe UI", sans-serif;
  box-shadow: 0 0 0 1px var(--mdd-widgets-line), 0 20px 44px -26px oklch(0.25 0.05 156 / 0.55);
  accent-color: var(--mdd-widgets-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(p, h3, h4, ol, ul) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; }
  & :focus-visible { outline: 2px solid var(--mdd-widgets-accent); outline-offset: 2px; }
}

.mdd-widgets-head {
  grid-area: head;
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  justify-content: space-between;
  gap: 8px 10px;
}
.mdd-widgets-eyebrow {
  font-size: 10.5px;
  font-weight: 650;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--mdd-widgets-muted);
}
.mdd-widgets-title {
  font-size: clamp(16px, 5.4cqi, 20px);
  font-weight: 690;
  letter-spacing: -0.022em;
  line-height: 1.15;
  text-wrap: balance;
}
.mdd-widgets-tools { display: flex; gap: 6px; flex: none; }
.mdd-widgets-edit, .mdd-widgets-reset, .mdd-widgets-restore {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  block-size: 30px;
  padding: 0 11px;
  border: 1px solid var(--mdd-widgets-line);
  border-radius: 9px;
  background: var(--mdd-widgets-card);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: background-color .2s, color .2s, border-color .2s, scale .25s var(--mdd-widgets-out);
  &:hover { border-color: color-mix(in oklch, var(--mdd-widgets-ink) 26%, transparent); }
  &:active { scale: 0.96; }
  & svg { inline-size: 14px; block-size: 14px; fill: none; stroke: currentColor; stroke-width: 1.5; }
}
.mdd-widgets-reset { color: var(--mdd-widgets-muted); &[hidden] { display: none; } }
.mdd-widgets-edit[aria-pressed="true"] {
  background: var(--mdd-widgets-ink);
  border-color: var(--mdd-widgets-ink);
  color: var(--mdd-widgets-card);
}
.mdd-widgets-help {
  grid-area: help;
  font-size: 11.5px;
  color: var(--mdd-widgets-muted);
  text-wrap: pretty;
  &[hidden] { display: none; }
}

.mdd-widgets-scroll {
  grid-area: scroll;
  max-block-size: 412px;
  overflow: auto;
  overscroll-behavior: contain;
  margin: -8px;
  padding: 8px;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--mdd-widgets-ink) 22%, transparent) transparent;
}
.mdd-widgets-board { position: relative; }
.mdd-widgets-cells, .mdd-widgets-grid {
  --mdd-widgets-cols: 3;
  display: grid;
  grid-template-columns: repeat(var(--mdd-widgets-cols), minmax(0, 1fr));
  grid-auto-rows: var(--mdd-widgets-row);
  gap: var(--mdd-widgets-gap);
}
.mdd-widgets-cells {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  transition: opacity .3s;
  & i {
    border-radius: 12px;
    border: 1.5px dashed color-mix(in oklch, var(--mdd-widgets-accent) 30%, transparent);
    background: color-mix(in oklch, var(--mdd-widgets-accent) 4%, transparent);
  }
}
.mdd-widgets[data-edit] .mdd-widgets-cells { opacity: 1; }
.mdd-widgets-grid { position: relative; }

/* ---------- card ---------- */
.mdd-widgets-card {
  container: mdd-widgets-card / size;
  position: relative;
  display: grid;
  grid-template-rows: auto 1fr;
  min-inline-size: 0;
  border-radius: 12px;
  background: var(--mdd-widgets-card);
  box-shadow: 0 0 0 1px var(--mdd-widgets-line), 0 1px 2px oklch(0.3 0.04 156 / 0.06);
  transition: box-shadow .25s, scale .35s var(--mdd-widgets-spring), rotate .35s var(--mdd-widgets-spring), opacity .3s;
  touch-action: auto;
  &[hidden] { display: none; }
  @starting-style { opacity: 0; scale: 0.9; }
}
.mdd-widgets-bar {
  display: flex;
  align-items: center;
  gap: 4px;
  min-inline-size: 0;
  padding: 8px 8px 0 10px;
  & h4 {
    flex: 1;
    min-inline-size: 0;
    font-size: 10.5px;
    font-weight: 650;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--mdd-widgets-muted);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
}
.mdd-widgets-grip {
  inline-size: 0;
  block-size: 14px;
  flex: none;
  margin-inline-start: -2px;
  opacity: 0;
  background: radial-gradient(circle, currentColor 1.1px, transparent 1.6px) 0 0 / 5px 5px;
  color: color-mix(in oklch, var(--mdd-widgets-ink) 45%, transparent);
  transition: inline-size .3s var(--mdd-widgets-out), opacity .2s;
}
.mdd-widgets-x {
  position: absolute;
  inset: -7px -7px auto auto;
  z-index: 1;
  display: grid;
  place-items: center;
  inline-size: 20px;
  block-size: 20px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: var(--mdd-widgets-card);
  box-shadow: 0 0 0 1px color-mix(in oklch, var(--mdd-widgets-ink) 18%, transparent), 0 2px 5px oklch(0.3 0.04 156 / 0.18);
  color: var(--mdd-widgets-muted);
  cursor: pointer;
  opacity: 0;
  scale: 0.6;
  pointer-events: none;
  transition: opacity .2s, scale .3s var(--mdd-widgets-spring), background-color .2s, color .2s;
  &::before {
    content: "";
    inline-size: 8px;
    block-size: 8px;
    background:
      linear-gradient(45deg, transparent calc(50% - 0.75px), currentColor 0 calc(50% + 0.75px), transparent 0),
      linear-gradient(-45deg, transparent calc(50% - 0.75px), currentColor 0 calc(50% + 0.75px), transparent 0);
  }
  &:hover { background: oklch(0.55 0.19 27); color: var(--mdd-widgets-card); box-shadow: 0 2px 6px oklch(0.45 0.15 27 / 0.35); }
}
.mdd-widgets-body { min-block-size: 0; padding: 3px 10px 8px; overflow: hidden; border-radius: 0 0 12px 12px; }
.mdd-widgets-big {
  font-size: clamp(17px, min(17cqi, 32cqb), 30px);
  font-weight: 660;
  letter-spacing: -0.035em;
  line-height: 1.05;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.mdd-widgets-delta {
  margin-block-start: 3px;
  font-size: 11px;
  color: var(--mdd-widgets-muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  & b { font-weight: 650; color: var(--mdd-widgets-accent); }
}

/* revenue */
.mdd-widgets-rev {
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-areas: "big spark" "delta spark";
  column-gap: 12px;
  align-content: center;
  & .mdd-widgets-big { grid-area: big; }
  & .mdd-widgets-delta { grid-area: delta; }
}
.mdd-widgets-spark {
  grid-area: spark;
  inline-size: 100%;
  block-size: 100%;
  min-block-size: 28px;
  max-block-size: 120px;
  align-self: stretch;
  overflow: visible;
}
.mdd-widgets-spark-fill { fill: color-mix(in oklch, var(--mdd-widgets-accent) 14%, transparent); }
.mdd-widgets-spark-line { fill: none; stroke: var(--mdd-widgets-accent); stroke-width: 1.75; vector-effect: non-scaling-stroke; stroke-linejoin: round; stroke-linecap: round; }
@container mdd-widgets-card (width < 190px) {
  .mdd-widgets-rev { grid-template-columns: 1fr; grid-template-areas: "big" "delta"; }
  .mdd-widgets-spark { display: none; }
}
@container mdd-widgets-card (height > 150px) {
  .mdd-widgets-rev { grid-template-columns: 1fr; grid-template-areas: "big" "delta" "spark"; row-gap: 6px; }
}

/* hourly bars */
.mdd-widgets-hours { display: grid; grid-template-rows: auto 1fr; gap: 6px; }
.mdd-widgets-peak {
  font-size: 11.5px;
  color: var(--mdd-widgets-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  & b { color: var(--mdd-widgets-ink); font-weight: 650; }
}
.mdd-widgets-bars {
  list-style: none;
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 1fr;
  align-items: end;
  gap: clamp(2px, 2.4cqi, 7px);
  min-block-size: 0;
  & li { display: grid; grid-template-rows: 1fr auto; block-size: 100%; gap: 3px; min-inline-size: 0; }
  & i {
    align-self: end;
    block-size: calc(var(--v) / 56 * 100%);
    border-radius: 3px 3px 1px 1px;
    background: color-mix(in oklch, var(--mdd-widgets-accent) 34%, var(--mdd-widgets-card));
    transform-origin: bottom;
  }
  & [data-peak] i { background: var(--mdd-widgets-crust); }
  & span {
    font-size: 9.5px;
    text-align: center;
    color: var(--mdd-widgets-muted);
    font-variant-numeric: tabular-nums;
  }
}
@container mdd-widgets-card (height < 120px) {
  .mdd-widgets-peak { display: none; }
  .mdd-widgets-bars span { display: none; }
}

/* top sellers */
.mdd-widgets-top ol {
  list-style: none;
  display: grid;
  gap: 7px;
  counter-reset: mdd-widgets-top;
  & li {
    position: relative;
    display: flex;
    justify-content: space-between;
    gap: 8px;
    padding-block-end: 5px;
    font-size: 12px;
    counter-increment: mdd-widgets-top;
    & span { min-inline-size: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & span::before { content: counter(mdd-widgets-top) "  "; font-family: ui-monospace, Menlo, monospace; font-size: 10px; color: var(--mdd-widgets-muted); white-space: pre; }
    & b { font-weight: 650; font-variant-numeric: tabular-nums; }
    &::after {
      content: "";
      position: absolute;
      inset: auto auto 0 0;
      block-size: 3px;
      inline-size: calc(var(--q) / 64 * 100%);
      border-radius: 2px;
      background: linear-gradient(90deg, var(--mdd-widgets-accent), color-mix(in oklch, var(--mdd-widgets-accent) 40%, var(--mdd-widgets-card)));
    }
  }
}
@container mdd-widgets-card (height < 150px) {
  .mdd-widgets-top li:nth-child(n + 3) { display: none; }
}
@container mdd-widgets-card (height < 90px) {
  .mdd-widgets-top li:nth-child(n + 2) { display: none; }
}

/* waste ring */
.mdd-widgets-waste {
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-areas: "ring big" "ring delta";
  column-gap: 9px;
  align-content: center;
  & .mdd-widgets-big { grid-area: big; font-size: clamp(17px, 14cqi, 26px); }
  & .mdd-widgets-delta { grid-area: delta; }
}
.mdd-widgets-ring {
  grid-area: ring;
  align-self: center;
  inline-size: clamp(24px, 22cqi, 40px);
  aspect-ratio: 1;
  border-radius: 50%;
  background:
    radial-gradient(closest-side, var(--mdd-widgets-card) 68%, transparent 70%),
    conic-gradient(var(--mdd-widgets-crust) calc(var(--p) * 1%), color-mix(in oklch, var(--mdd-widgets-ink) 9%, transparent) 0);
}
@container mdd-widgets-card (width < 150px) {
  .mdd-widgets-more { display: none; }
}
@container mdd-widgets-card (width < 100px) {
  .mdd-widgets-ring { display: none; }
  .mdd-widgets-waste { grid-template-columns: 1fr; grid-template-areas: "big" "delta"; }
}

/* staff */
.mdd-widgets-staff ul {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 6px 12px;
  align-content: center;
  block-size: 100%;
  & li { display: flex; align-items: center; gap: 7px; min-inline-size: 0; flex: 0 1 auto; }
  & span {
    display: grid;
    place-items: center;
    inline-size: 26px;
    block-size: 26px;
    flex: none;
    border-radius: 50%;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.02em;
    color: oklch(0.32 0.06 var(--h));
    background: oklch(0.9 0.06 var(--h));
    box-shadow: 0 0 0 2px var(--mdd-widgets-card);
  }
  & p { font-size: 12px; font-weight: 560; line-height: 1.15; white-space: nowrap; }
  & small { display: block; font-size: 10.5px; font-weight: 400; color: var(--mdd-widgets-muted); }
}
@container mdd-widgets-card (width < 230px) {
  .mdd-widgets-staff ul { flex-direction: column; flex-wrap: nowrap; align-content: start; justify-content: center; gap: 8px; }
}
@container mdd-widgets-card (width < 230px) and (height < 130px) {
  .mdd-widgets-staff ul { flex-direction: row; gap: 0; }
  .mdd-widgets-staff li + li { margin-inline-start: -7px; }
  .mdd-widgets-staff p { display: none; }
}
@container mdd-widgets-card (height < 80px) {
  .mdd-widgets-delta { margin-block-start: 1px; }
}

/* size badge + resize handle */
.mdd-widgets-size {
  position: absolute;
  inset: 50% auto auto 50%;
  translate: -50% -50%;
  padding: 4px 9px;
  border-radius: 999px;
  background: var(--mdd-widgets-ink);
  color: var(--mdd-widgets-card);
  font: 650 12px/1 ui-monospace, Menlo, monospace;
  font-variant-numeric: tabular-nums;
  opacity: 0;
  scale: 0.8;
  pointer-events: none;
  transition: opacity .15s, scale .3s var(--mdd-widgets-spring);
}
.mdd-widgets-resize {
  position: absolute;
  inset: auto 0 0 auto;
  inline-size: 22px;
  block-size: 22px;
  cursor: nwse-resize;
  touch-action: none;
  opacity: 0;
  pointer-events: none;
  transition: opacity .2s;
  &::before {
    content: "";
    position: absolute;
    inset: auto 5px 5px auto;
    inline-size: 9px;
    block-size: 9px;
    background:
      linear-gradient(-45deg, transparent 2px, currentColor 2px 3.2px, transparent 3.2px 5px, currentColor 5px 6.2px, transparent 6.2px);
    color: color-mix(in oklch, var(--mdd-widgets-ink) 45%, transparent);
  }
}

/* ---------- edit mode ---------- */
.mdd-widgets[data-edit] {
  -webkit-user-select: none;
  user-select: none;
  & .mdd-widgets-card {
    cursor: grab;
    touch-action: none;
    box-shadow: 0 0 0 1px color-mix(in oklch, var(--mdd-widgets-accent) 30%, transparent), 0 2px 6px oklch(0.3 0.04 156 / 0.08);
    &:hover { box-shadow: 0 0 0 1.5px color-mix(in oklch, var(--mdd-widgets-accent) 60%, transparent), 0 6px 14px -6px oklch(0.3 0.04 156 / 0.25); }
    &:focus-visible { outline-offset: 3px; }
  }
  & .mdd-widgets-grip { inline-size: 10px; opacity: 1; margin-inline-end: 3px; }
  & .mdd-widgets-x { opacity: 1; scale: 1; pointer-events: auto; transition-delay: calc(var(--i, 0) * 35ms); }
  & .mdd-widgets-resize { opacity: 1; pointer-events: auto; }
  & .mdd-widgets-body { pointer-events: none; }
}
.mdd-widgets-card[data-lifted] {
  position: absolute;
  inset: 0 auto auto 0;
  z-index: 3;
  grid-column: auto !important;
  grid-row: auto !important;
  scale: 1.035;
  rotate: -1.2deg;
  cursor: grabbing;
  box-shadow: 0 0 0 1.5px var(--mdd-widgets-accent), 0 22px 38px -14px oklch(0.25 0.06 156 / 0.45);
  will-change: translate;
}
.mdd-widgets-card[data-kbd] {
  z-index: 2;
  scale: 1.03;
  box-shadow: 0 0 0 2px var(--mdd-widgets-accent), 0 16px 30px -14px oklch(0.25 0.06 156 / 0.45);
}
.mdd-widgets-card[data-landing] { transition: none; }
.mdd-widgets-card:is([data-resizing], [data-kbd-size]) .mdd-widgets-size { opacity: 1; scale: 1; }
.mdd-widgets-card[data-resizing] { box-shadow: 0 0 0 2px var(--mdd-widgets-accent), 0 10px 22px -12px oklch(0.25 0.06 156 / 0.4); }
.mdd-widgets-ghost {
  border-radius: 12px;
  border: 2px dashed color-mix(in oklch, var(--mdd-widgets-accent) 70%, transparent);
  background:
    repeating-linear-gradient(-45deg, color-mix(in oklch, var(--mdd-widgets-accent) 10%, transparent) 0 6px, transparent 6px 12px);
  background-size: 17px 17px;
  animation: mdd-widgets-march 1.2s linear infinite;
}
@keyframes mdd-widgets-march { to { background-position: 17px 0; } }

/* ---------- empty + tray ---------- */
.mdd-widgets-empty {
  grid-column: 1 / -1;
  grid-row: span 3;
  display: none;
  place-content: center;
  justify-items: center;
  gap: 10px;
  padding: 16px;
  text-align: center;
  border-radius: 12px;
  border: 1.5px dashed var(--mdd-widgets-line);
  & svg { inline-size: 30px; block-size: 30px; fill: none; stroke: var(--mdd-widgets-muted); stroke-width: 1.4; }
  & p { max-inline-size: 30ch; font-size: 12px; color: var(--mdd-widgets-muted); text-wrap: pretty; }
  & b { display: block; margin-block-end: 2px; font-size: 13px; color: var(--mdd-widgets-ink); }
}
.mdd-widgets-grid:not(:has(.mdd-widgets-card:not([hidden]))) .mdd-widgets-empty { display: grid; }
.mdd-widgets-restore { background: var(--mdd-widgets-ink); color: var(--mdd-widgets-card); border-color: var(--mdd-widgets-ink); }

.mdd-widgets-tray {
  grid-area: tray;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  padding-block-start: 10px;
  border-block-start: 1px solid var(--mdd-widgets-line);
  &[hidden] { display: none; }
  @starting-style { opacity: 0; translate: 0 6px; }
  transition: opacity .3s, translate .4s var(--mdd-widgets-out);
}
.mdd-widgets-tray-label {
  font-size: 10.5px;
  font-weight: 650;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--mdd-widgets-muted);
  margin-inline-end: 4px;
}
.mdd-widgets-tray-list { display: contents; }
.mdd-widgets-tray-none { font-size: 11.5px; color: var(--mdd-widgets-muted); }
.mdd-widgets-tray:has(.mdd-widgets-chip) .mdd-widgets-tray-none { display: none; }
.mdd-widgets-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  block-size: 26px;
  padding: 0 10px 0 7px;
  border: 1px dashed color-mix(in oklch, var(--mdd-widgets-accent) 55%, transparent);
  border-radius: 999px;
  background: var(--mdd-widgets-card);
  font-size: 11.5px;
  font-weight: 560;
  cursor: pointer;
  & svg { inline-size: 12px; block-size: 12px; fill: none; stroke: var(--mdd-widgets-accent); stroke-width: 1.8; stroke-linecap: round; }
  &:hover { background: var(--mdd-widgets-tint); border-style: solid; }
  &:active { scale: 0.95; }
  @starting-style { opacity: 0; scale: 0.8; }
  transition: opacity .25s, scale .35s var(--mdd-widgets-spring), background-color .2s;
}

.mdd-widgets-sr {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* first paint: bars grow, cards rise in order */
.mdd-widgets-bars i { animation: mdd-widgets-grow .7s var(--mdd-widgets-spring) both; animation-delay: calc(var(--i) * 45ms + 120ms); }
@keyframes mdd-widgets-grow { from { transform: scaleY(0); } }
.mdd-widgets-spark { animation: mdd-widgets-draw 1.1s var(--mdd-widgets-out) both .2s; }
@keyframes mdd-widgets-draw { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 -2px 0 0); } }
.mdd-widgets-ring { animation: mdd-widgets-ring 1s var(--mdd-widgets-out) both .25s; }
@keyframes mdd-widgets-ring { from { --mdd-widgets-sweep: 0; } to { --mdd-widgets-sweep: 1; } }
.mdd-widgets-ring { background:
    radial-gradient(closest-side, var(--mdd-widgets-card) 68%, transparent 70%),
    conic-gradient(var(--mdd-widgets-crust) calc(var(--p) * var(--mdd-widgets-sweep) * 1%), color-mix(in oklch, var(--mdd-widgets-ink) 9%, transparent) 0); }

@container (width < 300px) {
  .mdd-widgets-cells, .mdd-widgets-grid { --mdd-widgets-cols: 2; }
}
@container (width >= 520px) {
  .mdd-widgets-cells, .mdd-widgets-grid { --mdd-widgets-cols: 4; }
}

@media (prefers-reduced-motion: reduce) {
  .mdd-widgets-card, .mdd-widgets-x, .mdd-widgets-size, .mdd-widgets-chip, .mdd-widgets-tray, .mdd-widgets-grip { transition: opacity .2s, background-color .2s, box-shadow .2s; }
  .mdd-widgets-card { @starting-style { opacity: 0; scale: 1; } }
  .mdd-widgets-card[data-lifted], .mdd-widgets-card[data-kbd] { scale: 1; rotate: 0deg; }
  .mdd-widgets-bars i, .mdd-widgets-spark, .mdd-widgets-ring { animation: none; }
  .mdd-widgets-ring { --mdd-widgets-sweep: 1; }
  .mdd-widgets-ghost { animation: none; }
}

