const SPRING = "linear(0, 0.046, 0.156, 0.297, 0.446, 0.588, 0.712, 0.815, 0.896, 0.957, 0.998, 1.025, 1.039, 1.045, 1.045, 1.041, 1.035, 1.029, 1.022, 1.016, 1.011, 1.006, 1.003, 1.001, 0.999, 0.998, 1)";
const MAX_H = 3;
/* Default layout for the 3-column grid: x, y in cells; w, h in spans. */
const DEFAULT3 = [
  { id: "revenue", x: 0, y: 0, w: 2, h: 1 }, { id: "orders", x: 2, y: 0, w: 1, h: 1 },
  { id: "hourly", x: 0, y: 1, w: 2, h: 2 }, { id: "ticket", x: 2, y: 1, w: 1, h: 1 },
  { id: "waste", x: 2, y: 2, w: 1, h: 1 }, { id: "top", x: 0, y: 3, w: 2, h: 2 },
