  --mdd-split-faint: color-mix(in oklch, var(--mdd-split-ink) 32%, var(--mdd-split-bg));
  --mdd-split-raised: color-mix(in oklch, var(--mdd-split-ink) 6%, var(--mdd-split-panel));
  --mdd-split-mono: ui-monospace, Menlo, "SF Mono", monospace;
  --mdd-split-spring: linear(0, 0.046, 0.156, 0.297, 0.446, 0.588, 0.712, 0.815, 0.896, 0.957, 0.998, 1.025, 1.039, 1.045, 1.045, 1.041, 1.035, 1.029, 1.022, 1.016, 1.011, 1.006, 1.003, 1.001, 0.999, 0.998, 1);
  --mdd-split-out: cubic-bezier(.16, 1, .3, 1);
  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head" "frame" "foot";
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr) auto;
  inline-size: 100%;
  max-inline-size: 640px;
  block-size: clamp(330px, 96cqi, 400px);
  box-sizing: border-box;
  border-radius: 14px;
  overflow: hidden;
  background: var(--mdd-split-bg);
  color: var(--mdd-split-ink);
  font: 400 12.5px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  box-shadow: 0 0 0 1px var(--mdd-split-line), 0 24px 50px -28px oklch(0 0 0 / 0.8);
  accent-color: var(--mdd-split-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(p, ul, pre, table) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; }
  & :focus-visible { outline: 2px solid var(--mdd-split-accent); outline-offset: -2px; }
}

/* ---------- header ---------- */
.mdd-split-head {
  grid-area: head;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 8px 8px 12px;
  border-block-end: 1px solid var(--mdd-split-line);
}
.mdd-split-file {
  display: flex;
  align-items: center;
  gap: 6px;
  min-inline-size: 0;
  margin-inline-end: auto;
  font: 500 12px/1 var(--mdd-split-mono);
  color: var(--mdd-split-ink);
  & svg { inline-size: 15px; block-size: 15px; flex: none; fill: none; stroke: var(--mdd-split-muted); stroke-width: 1.3; stroke-linejoin: round; }
  & span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.mdd-split-env {
  display: flex;
  padding: 2px;
  border-radius: 7px;
  background: color-mix(in oklch, var(--mdd-split-ink) 7%, transparent);
  & button {
    block-size: 22px;
    padding: 0 8px;
    border: 0;
    border-radius: 5px;
    background: transparent;
    color: var(--mdd-split-muted);
    font: 500 11px/1 var(--mdd-split-mono);
    cursor: pointer;
    transition: background-color .2s, color .2s;
    &:hover { color: var(--mdd-split-ink); }
    &[aria-checked="true"] { background: var(--mdd-split-raised); color: var(--mdd-split-ink); box-shadow: 0 1px 2px oklch(0 0 0 / 0.4); }
    &[data-env="staging"][aria-checked="true"] { color: oklch(0.85 0.12 75); }
  }
}
.mdd-split-run {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  block-size: 26px;
  padding: 0 11px 0 8px;
  border: 0;
  border-radius: 7px;
  background: var(--mdd-split-accent);
  color: oklch(0.2 0.04 125);
  font-weight: 650;
  font-size: 12px;
  cursor: pointer;
  transition: filter .2s, scale .2s var(--mdd-split-out);
  & svg { inline-size: 12px; block-size: 12px; fill: currentColor; }
  &:hover { filter: brightness(1.06); }
  &:active { scale: 0.95; }
  &[aria-disabled="true"] { cursor: progress; background: color-mix(in oklch, var(--mdd-split-accent) 35%, var(--mdd-split-bg)); color: var(--mdd-split-ink); }
  &[aria-disabled="true"] svg { animation: mdd-split-pulse 0.9s ease-in-out infinite alternate; }
  &:focus-visible { outline-offset: 2px; }
}
@keyframes mdd-split-pulse { to { opacity: 0.3; } }

/* ---------- frame + splits ---------- */
.mdd-split-frame {
  --mdd-split-a: 34%;
  grid-area: frame;
  display: grid;
  grid-template-columns: var(--mdd-split-a) 1px minmax(0, 1fr);
  min-inline-size: 0;
  min-block-size: 0;
  transition: grid-template-columns .55s var(--mdd-split-spring);
}
.mdd-split-main {
  --mdd-split-b: 50%;
  display: grid;
  grid-template-rows: var(--mdd-split-b) 1px minmax(0, 1fr);
  min-inline-size: 0;
  min-block-size: 0;
  transition: grid-template-rows .55s var(--mdd-split-spring);
}
.mdd-split[data-dragging] :is(.mdd-split-frame, .mdd-split-main) { transition: none; }
.mdd-split[data-dragging] { cursor: var(--mdd-split-cursor); user-select: none; }

.mdd-split-bar {
  position: relative;
  z-index: 2;
  background: var(--mdd-split-line);
  touch-action: none;
  transition: background-color .2s;
  &::before {
    content: "";
    position: absolute;
    inset: 0 -5px;
  }
  &::after {
    content: "";
    position: absolute;
    inset-block: calc(50% - 14px);
    inset-inline: -2px;
    border-radius: 3px;
    background: var(--mdd-split-faint);
    opacity: 0;
    scale: 1 0.5;
    transition: opacity .2s, scale .35s var(--mdd-split-spring), background-color .2s;
  }
  &[data-split="a"] { cursor: col-resize; }
  &[data-split="b"] {
    cursor: row-resize;
    &::before { inset: -5px 0; }
    &::after { inset-inline: calc(50% - 14px); inset-block: -2px; scale: 0.5 1; }
  }
  &:hover::after, &:focus-visible::after, &[data-active]::after { opacity: 1; scale: 1; }
  &:hover, &[data-active] { background: color-mix(in oklch, var(--mdd-split-ink) 22%, transparent); }
  &[data-active]::after { background: var(--mdd-split-accent); }
  &:focus-visible { outline: none; background: var(--mdd-split-accent); }
  &[data-armed] { background: var(--mdd-split-danger); &::after { background: var(--mdd-split-danger); } }
}
.mdd-split-tip {
  position: absolute;
  inset: 50% auto auto 50%;
  translate: 8px -50%;
  z-index: 3;
  padding: 3px 7px;
  border-radius: 6px;
  background: var(--mdd-split-ink);
  color: var(--mdd-split-bg);
  font: 600 10.5px/1.2 var(--mdd-split-mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  scale: 0.9;
  transition: opacity .15s, scale .25s var(--mdd-split-out);
  [data-split="b"] > & { translate: -50% 8px; }
  [data-show] > & { opacity: 1; scale: 1; }
  [data-armed] > & { background: var(--mdd-split-danger); }
}

/* panes */
.mdd-split-side, .mdd-split-results {
  container-type: inline-size;
  position: relative;
  min-inline-size: 0;
  min-block-size: 0;
  overflow: hidden;
  background: var(--mdd-split-panel);
}
.mdd-split-pane {
  block-size: 100%;
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--mdd-split-ink) 22%, transparent) transparent;
  transition: opacity .25s, filter .35s;
}
.mdd-split-rail {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 6px;
  border: 0;
  background: var(--mdd-split-panel);
  color: var(--mdd-split-muted);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
  opacity: 0;
  visibility: hidden;
  transition: opacity .25s, visibility 0s .25s, color .2s, background-color .2s;
  & svg { inline-size: 14px; block-size: 14px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; }
  & small { font: 500 10.5px/1 var(--mdd-split-mono); letter-spacing: 0; text-transform: none; color: var(--mdd-split-faint); }
  &:hover { color: var(--mdd-split-ink); background: var(--mdd-split-raised); }
}
.mdd-split-side .mdd-split-rail { flex-direction: column; & span { writing-mode: vertical-rl; rotate: 180deg; } }
.mdd-split-results .mdd-split-rail { padding: 0 12px; justify-content: flex-start; }
[data-collapsed] > .mdd-split-rail { opacity: 1; visibility: visible; transition: opacity .3s .12s, visibility 0s, color .2s, background-color .2s; }
[data-collapsed] > .mdd-split-pane, [data-armed-pane] > .mdd-split-pane { opacity: 0.25; filter: blur(2px) grayscale(1); }
[data-collapsed] > .mdd-split-pane { visibility: hidden; transition: opacity .2s, filter .2s, visibility 0s .2s; }

/* schema tree */
.mdd-split-label {
  padding: 10px 12px 6px;
  font: 600 10px/1 var(--mdd-split-mono);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--mdd-split-faint);
  white-space: nowrap;
}
.mdd-split-tree {
  list-style: none;
  padding-block-end: 10px;
  & ul { list-style: none; padding: 0; }
  & li { outline: none; }
  & li[aria-expanded="false"] > ul { display: none; }
  & li:focus-visible > span { outline: 2px solid var(--mdd-split-accent); outline-offset: -2px; }
}
.mdd-split-t, .mdd-split-c {
  display: flex;
  align-items: center;
  gap: 5px;
  min-inline-size: 0;
  padding: 4px 10px 4px 8px;
  font: 500 11.5px/1.25 var(--mdd-split-mono);
  white-space: nowrap;
  cursor: default;
  & small, & i { margin-inline-start: auto; padding-inline-start: 6px; font-style: normal; font-size: 10px; color: var(--mdd-split-faint); }
}
.mdd-split-t {
  cursor: pointer;
  & svg { inline-size: 12px; block-size: 12px; flex: none; fill: none; stroke: var(--mdd-split-muted); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; transition: rotate .3s var(--mdd-split-out); }
  [aria-expanded="true"] > & svg { rotate: 90deg; }
  &:hover { background: color-mix(in oklch, var(--mdd-split-ink) 5%, transparent); }
}
.mdd-split-c {
  padding-inline-start: 25px;
  color: var(--mdd-split-muted);
  overflow: hidden;
  &:hover { color: var(--mdd-split-ink); }
}
.mdd-split-tree li[aria-expanded="true"] > ul > li { animation: mdd-split-in .35s var(--mdd-split-out) both; animation-delay: calc(var(--i, 0) * 28ms); }
@keyframes mdd-split-in { from { opacity: 0; translate: -4px 0; } }

/* editor */
.mdd-split-editor {
  container-type: inline-size;
  min-block-size: 0;
  overflow: auto;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--mdd-split-ink) 22%, transparent) transparent;
  & pre { padding: 8px 0 12px; font: 400 11.5px/1.6 var(--mdd-split-mono); counter-reset: mdd-split-ln; tab-size: 2; }
  & code { font: inherit; }
  & b { font-weight: inherit; }
  & .k { color: var(--mdd-split-accent); }
  & .f { color: oklch(0.84 0.09 210); }
  & .s { color: oklch(0.84 0.1 75); }
  & .o { color: oklch(0.8 0.12 30); }
  & .c { color: var(--mdd-split-faint); font-style: italic; }
}
.mdd-split-l {
  counter-increment: mdd-split-ln;
  &::before {
    content: counter(mdd-split-ln);
    display: inline-block;
    inline-size: 3.2ch;
    margin-inline-end: 1.4ch;
    padding-inline-end: 0.6ch;
    text-align: end;
    color: var(--mdd-split-faint);
    opacity: 0.7;
  }
}

/* results */
.mdd-split-results .mdd-split-pane { display: grid; }
.mdd-split-grid, .mdd-split-loading, .mdd-split-error { grid-area: 1 / 1; min-inline-size: 0; }
.mdd-split-loading, .mdd-split-error { display: none; }
.mdd-split-results[data-state="loading"] { & .mdd-split-loading { display: grid; } & .mdd-split-grid { display: none; } }
.mdd-split-results[data-state="error"] { & .mdd-split-error { display: grid; } & .mdd-split-grid { display: none; } }
.mdd-split-grid table {
  inline-size: 100%;
  border-collapse: collapse;
  font: 400 11.5px/1.3 var(--mdd-split-mono);
  font-variant-numeric: tabular-nums;
  & th {
    position: sticky;
    inset-block-start: 0;
    z-index: 1;
    padding: 7px 10px 6px;
    background: var(--mdd-split-raised);
    color: var(--mdd-split-muted);
    font-weight: 600;
    font-size: 10.5px;
    text-align: start;
    white-space: nowrap;
    box-shadow: inset 0 -1px var(--mdd-split-line);
  }
  & th:not(:first-child), & td:not(:first-child) { text-align: end; }
  & td { padding: 6px 10px; white-space: nowrap; border-block-end: 1px solid color-mix(in oklch, var(--mdd-split-ink) 5%, transparent); }
  & tbody tr { animation: mdd-split-in .4s var(--mdd-split-out) both; animation-delay: calc(var(--i, 0) * 40ms); }
  & tbody tr:hover { background: color-mix(in oklch, var(--mdd-split-ink) 4%, transparent); }
}
.mdd-split-pct {
  display: inline-grid;
  grid-template-columns: 34px;
  align-items: center;
  gap: 7px;
  & i {
    display: none;
    block-size: 4px;
    border-radius: 2px;
    background: linear-gradient(90deg, var(--mdd-split-accent) var(--w), color-mix(in oklch, var(--mdd-split-ink) 10%, transparent) 0);
  }
}
.mdd-split-loading {
  align-content: start;
  gap: 9px;
  padding: 12px 10px;
  & i {
    block-size: 10px;
    border-radius: 4px;
    inline-size: calc(100% - var(--i) * 9%);
    background: linear-gradient(90deg, color-mix(in oklch, var(--mdd-split-ink) 7%, transparent) 30%, color-mix(in oklch, var(--mdd-split-ink) 16%, transparent) 50%, color-mix(in oklch, var(--mdd-split-ink) 7%, transparent) 70%) 0 0 / 300% 100%;
    animation: mdd-split-shimmer 1.1s linear infinite;
    animation-delay: calc(var(--i) * -120ms);
  }
}
@keyframes mdd-split-shimmer { from { background-position: 100% 0; } to { background-position: 0 0; } }
.mdd-split-error {
  align-content: start;
  gap: 4px;
  padding: 10px 12px;
  border-inline-start: 2px solid var(--mdd-split-danger);
  background: linear-gradient(90deg, color-mix(in oklch, var(--mdd-split-danger) 10%, transparent), transparent 70%);
  font: 400 11px/1.45 var(--mdd-split-mono);
  color: var(--mdd-split-muted);
  & b { color: var(--mdd-split-danger); font-weight: 650; margin-inline-end: 4px; }
  & p:first-child { color: var(--mdd-split-ink); }
  & .mdd-split-hint { margin-block-start: 4px; font-family: system-ui, sans-serif; font-size: 11.5px; text-wrap: pretty; }
}

/* ---------- footer ---------- */
.mdd-split-foot {
  grid-area: foot;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px 12px;
  border-block-start: 1px solid var(--mdd-split-line);
  font: 400 10.5px/1.2 var(--mdd-split-mono);
  font-variant-numeric: tabular-nums;
  color: var(--mdd-split-muted);
  & [data-status] { min-inline-size: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.mdd-split-dot {
  inline-size: 6px;
  block-size: 6px;
  flex: none;
  border-radius: 50%;
  background: var(--mdd-split-accent);
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--mdd-split-accent) 18%, transparent);
  .mdd-split[data-state="error"] & { background: var(--mdd-split-danger); box-shadow: 0 0 0 3px color-mix(in oklch, var(--mdd-split-danger) 18%, transparent); }
  .mdd-split[data-state="loading"] & { animation: mdd-split-pulse .6s ease-in-out infinite alternate; }
}
.mdd-split-org { margin-inline-start: auto; white-space: nowrap; color: var(--mdd-split-faint); font-family: system-ui, sans-serif; }

.mdd-split-sr {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* each pane answers to its own width, so dragging a divider re-lays the content live */
@container (width >= 300px) {
  .mdd-split-pct { grid-template-columns: 42px 36px; & i { display: block; } }
}
@container (width < 190px) {
  .mdd-split-l::before { inline-size: 2ch; margin-inline-end: 1ch; padding: 0; }
}
@container (width < 150px) {
  .mdd-split-c i, .mdd-split-t small { display: none; }
}
@container (width < 360px) {
  .mdd-split-org { display: none; }
  .mdd-split-env button { padding: 0 6px; }
  .mdd-split-editor pre { font-size: 10.5px; }
}
@container (width < 300px) {
  .mdd-split-file span { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .mdd-split-frame, .mdd-split-main { transition: none; }
  .mdd-split-bar::after, .mdd-split-tip { transition: opacity .15s; scale: 1; }
  .mdd-split-tree li[aria-expanded="true"] > ul > li, .mdd-split-grid tbody tr { animation: none; }
  .mdd-split-loading i { animation: none; background: color-mix(in oklch, var(--mdd-split-ink) 10%, transparent); }
  .mdd-split-run[aria-disabled="true"] svg, .mdd-split[data-state="loading"] .mdd-split-dot { animation: none; }
  .mdd-split-pane { transition: opacity .2s; filter: none !important; }
  .mdd-split-t svg { transition: none; }
}

