const $ = (s) => root.querySelector(s);
const frame = $(".mdd-split-frame");
const main = $(".mdd-split-main");
const side = $(".mdd-split-side");
const results = $(".mdd-split-results");
const tbody = $(".mdd-split-grid tbody");
const runBtn = $(".mdd-split-run");
const status = $("[data-status]");
const railCount = $("[data-rail-count]");
const live = $(".mdd-split-sr");
const reduce = () => matchMedia("(prefers-reduced-motion: reduce)").matches;
const uid = "mdd-split-" + Math.random().toString(36).slice(2, 8);
side.id = uid + "-side";
results.id = uid + "-results";
const say = (m) => { live.textContent = ""; requestAnimationFrame(() => { if (!root.isConnected) return; live.textContent = m; }); };

/* lane, shipments, on-time share — 412 + 288 + 641 + 197 + 533 + 359 = 2,430 */
const ROWS = [["SEA–PDX", 412, 0.968], ["OAK–RNO", 288, 0.955], ["LAX–PHX", 641, 0.941], ["DEN–SLC", 197, 0.919], ["ORD–MSP", 533, 0.902], ["ATL–CLT", 359, 0.874]];
const TOTAL = ROWS.reduce((s, r) => s + r[1], 0);
function renderRows() {
  tbody.innerHTML = ROWS.map((r, i) =>
    '<tr style="--i:' + i + '"><td>' + r[0] + "</td><td>" + r[1].toLocaleString("en-US") + '</td><td><span class="mdd-split-pct"><i style="--w:' + (r[2] * 100).toFixed(1) + '%"></i>' + (r[2] * 100).toFixed(1) + "%</span></td></tr>").join("");
}
renderRows();

/* ---------- splits ---------- */
const SPL = {
  a: { bar: $('[data-split="a"]'), host: frame, axis: "x", prop: "--mdd-split-a", pane: side, collapses: "first", minFirst: 116, minSecond: 150, rail: 28, f: 0.34, def: 0.34, collapsed: false, name: "Schema panel" },
  b: { bar: $('[data-split="b"]'), host: main, axis: "y", prop: "--mdd-split-b", pane: results, collapses: "second", minFirst: 56, minSecond: 66, rail: 30, f: 0.5, def: 0.5, collapsed: false, name: "Results panel" }
};
for (const s of Object.values(SPL)) {
  s.bar.setAttribute("aria-controls", s.pane.id);
  s.bar.setAttribute("aria-valuemin", "0");
  s.bar.setAttribute("aria-valuemax", "100");
}
const len = (s) => (s.axis === "x" ? s.host.clientWidth : s.host.clientHeight);
function bounds(s) {
  const H = len(s);
  return { H, lo: s.minFirst, hi: Math.max(s.minFirst, H - 1 - s.minSecond) };
}
function firstPx(s) {
  const { H } = bounds(s);
  if (s.collapsed) return s.collapses === "first" ? s.rail : H - 1 - s.rail;
  return s.f * H;
}
function write(s, px) {
  const { H } = bounds(s);
  if (px == null) {
    s.host.style.setProperty(s.prop, s.collapsed ? (s.collapses === "first" ? s.rail + "px" : "calc(100% - " + (s.rail + 1) + "px)") : (s.f * 100).toFixed(3) + "%");
  } else s.host.style.setProperty(s.prop, ((px / H) * 100).toFixed(3) + "%");
}
function aria(s) {
  const { H, lo, hi } = bounds(s);
  const now = s.collapsed ? (s.collapses === "first" ? 0 : 100) : Math.round(s.f * 100);
  s.bar.setAttribute("aria-valuenow", String(now));
  const pct = s.collapses === "first" ? now : 100 - now;
  s.bar.setAttribute("aria-valuetext", s.collapsed ? s.name + " collapsed" : s.name + " " + pct + " percent");
  s.pane.toggleAttribute("data-collapsed", s.collapsed);
  s.pane.querySelector(".mdd-split-pane").inert = s.collapsed;
  s.pane.querySelector(".mdd-split-rail").inert = !s.collapsed;
  return { H, lo, hi };
}
function apply(s) { write(s); aria(s); }
function tip(s, text, ms) {
  s.bar.querySelector(".mdd-split-tip").textContent = text;
  s.bar.setAttribute("data-show", "");
  clearTimeout(s.tt);
