  runBtn.querySelector("span").textContent = "Running";
  results.dataset.state = "loading";
  root.dataset.state = "loading";
  status.textContent = "Running on " + env + "…";
  if (SPL.b.collapsed) setCollapsed(SPL.b, false);
  const ms = env === "replica" ? 36 + Math.round(Math.random() * 14) : 9;
  setTimeout(() => {
    if (!root.isConnected) return;
    running = false;
    runBtn.removeAttribute("aria-disabled");
    runBtn.querySelector("span").textContent = "Run";
    if (env === "staging") {
      results.dataset.state = root.dataset.state = "error";
      status.textContent = "ERROR 42P01 · " + ms + " ms";
      railCount.textContent = "error";
      say("Query failed on staging. Relation lanes does not exist.");
    } else {
      renderRows();
      results.dataset.state = root.dataset.state = "ok";
      status.textContent = ROWS.length + " rows · " + TOTAL.toLocaleString("en-US") + " shipments · " + ms + " ms";
      railCount.textContent = ROWS.length + " rows";
      say(ROWS.length + " rows returned in " + ms + " milliseconds.");
    }
  }, reduce() ? 300 : 700);
}
runBtn.addEventListener("click", run);
root.addEventListener("keydown", (e) => {
  if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) { e.preventDefault(); run(); }
});

/* environment radios */
const radios = [...root.querySelectorAll(".mdd-split-env [role=radio]")];
function pick(b, focus) {
  for (const r of radios) { const on = r === b; r.setAttribute("aria-checked", String(on)); r.tabIndex = on ? 0 : -1; }
  env = b.dataset.env;
  if (focus) b.focus();
  status.textContent = "Connected to " + env + " · press Run";
}
radios.forEach((b, i) => {
  b.addEventListener("click", () => pick(b, false));
  b.addEventListener("keydown", (e) => {
    if (e.key !== "ArrowLeft" && e.key !== "ArrowRight" && e.key !== "ArrowUp" && e.key !== "ArrowDown") return;
    e.preventDefault();
    const d = e.key === "ArrowLeft" || e.key === "ArrowUp" ? -1 : 1;
    pick(radios[(i + d + radios.length) % radios.length], true);
  });
});

/* ---------- schema tree ---------- */
const tree = $(".mdd-split-tree");
tree.querySelectorAll("ul[role=group]").forEach((g) => [...g.children].forEach((li, i) => li.style.setProperty("--i", i)));
const shown = () => [...tree.querySelectorAll("[role=treeitem]")].filter((li) => li.offsetParent !== null || li.getClientRects().length);
function focusItem(li) {
  tree.querySelectorAll("[role=treeitem]").forEach((x) => (x.tabIndex = x === li ? 0 : -1));
