/* ---------- start ---------- */
if (root.clientWidth < 330) SPL.a.collapsed = true;
apply(SPL.a);
apply(SPL.b);
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  for (const s of Object.values(SPL)) {
    if (s.collapsed) { aria(s); continue; }
    const { H, lo, hi } = bounds(s);
    const px = s.f * H;
    if (px < lo - 0.5 || px > hi + 0.5) setOpen(s, s.f, false); else aria(s);
  }
});
ro.observe(frame);

