@property --mdd-transfer-fade-l { syntax: "<length>"; inherits: false; initial-value: 0px; }
@property --mdd-transfer-fade-r { syntax: "<length>"; inherits: false; initial-value: 24px; }

.mdd-transfer {
  --mdd-transfer-bg: oklch(0.205 0.005 265);
  --mdd-transfer-panel: oklch(0.24 0.006 265);
  --mdd-transfer-ink: oklch(0.95 0.006 80);
  --mdd-transfer-accent: oklch(0.76 0.14 35);
  --mdd-transfer-line: color-mix(in oklch, var(--mdd-transfer-ink) 10%, transparent);
  --mdd-transfer-muted: color-mix(in oklch, var(--mdd-transfer-ink) 56%, var(--mdd-transfer-bg));
  --mdd-transfer-faint: color-mix(in oklch, var(--mdd-transfer-ink) 30%, var(--mdd-transfer-bg));
  --mdd-transfer-sel: color-mix(in oklch, var(--mdd-transfer-accent) 17%, var(--mdd-transfer-panel));
  --mdd-transfer-mono: ui-monospace, Menlo, monospace;
  --mdd-transfer-spring: linear(0, 0.046, 0.156, 0.297, 0.446, 0.588, 0.712, 0.815, 0.896, 0.957, 0.998, 1.025, 1.039, 1.045, 1.045, 1.041, 1.035, 1.029, 1.022, 1.016, 1.011, 1.006, 1.003, 1.001, 0.999, 0.998, 1);
  --mdd-transfer-out: cubic-bezier(.16, 1, .3, 1);
  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head" "body" "preview" "hint";
  gap: 12px;
  inline-size: 100%;
  max-inline-size: 460px;
  box-sizing: border-box;
  padding: 16px 14px 14px;
  border-radius: 16px;
  background: var(--mdd-transfer-bg);
  color: var(--mdd-transfer-ink);
  font: 400 12.5px/1.35 system-ui, -apple-system, "Segoe UI", sans-serif;
  box-shadow: 0 0 0 1px var(--mdd-transfer-line), 0 26px 50px -28px oklch(0 0 0 / 0.85);
  accent-color: var(--mdd-transfer-accent);
  -webkit-user-select: none;
  user-select: none;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(p, h3, ul) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; }
  & :focus-visible { outline: 2px solid var(--mdd-transfer-accent); outline-offset: 2px; }
}

.mdd-transfer-head {
  grid-area: head;
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-areas: "eyebrow reset" "title reset";
  align-items: end;
}
.mdd-transfer-eyebrow {
  grid-area: eyebrow;
  font-size: 10.5px;
  font-weight: 650;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--mdd-transfer-muted);
}
.mdd-transfer-title {
  grid-area: title;
  font-size: clamp(17px, 5.6cqi, 21px);
  font-weight: 680;
  letter-spacing: -0.02em;
  line-height: 1.15;
  text-wrap: balance;
}
.mdd-transfer-reset {
  grid-area: reset;
  block-size: 28px;
  padding: 0 11px;
  border: 1px solid var(--mdd-transfer-line);
  border-radius: 8px;
  background: transparent;
  color: var(--mdd-transfer-muted);
  font-size: 12px;
  font-weight: 560;
  cursor: pointer;
  transition: color .2s, border-color .2s, opacity .2s;
  &:hover:not(:disabled) { color: var(--mdd-transfer-ink); border-color: color-mix(in oklch, var(--mdd-transfer-ink) 26%, transparent); }
  &:disabled { opacity: 0.4; cursor: default; }
}

/* ---------- two lists + controls ---------- */
.mdd-transfer-body {
  grid-area: body;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 34px minmax(0, 1fr);
  grid-template-rows: auto 1fr;
  grid-template-areas: "a . b" "a ctrl b";
  column-gap: 8px;
}
.mdd-transfer-col {
  display: grid;
  grid-template-rows: subgrid;
  grid-row: span 2;
  row-gap: 6px;
  min-inline-size: 0;
  &[data-list="avail"] { grid-area: a; }
  &[data-list="shown"] { grid-area: b; }
}
.mdd-transfer-label {
  display: flex;
  align-items: baseline;
  gap: 6px;
  font-size: 11px;
  font-weight: 650;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--mdd-transfer-muted);
  & b { font: 600 11px/1 var(--mdd-transfer-mono); letter-spacing: 0; color: var(--mdd-transfer-faint); font-variant-numeric: tabular-nums; }
}
.mdd-transfer-box {
  position: relative;
  block-size: 236px;
  border-radius: 11px;
  background: var(--mdd-transfer-panel);
  box-shadow: inset 0 0 0 1px var(--mdd-transfer-line);
  transition: box-shadow .2s, background-color .2s;
  &:has(.mdd-transfer-list:focus-visible) { box-shadow: inset 0 0 0 1px var(--mdd-transfer-line), 0 0 0 2px var(--mdd-transfer-accent); }
  [data-target] > & { box-shadow: inset 0 0 0 1.5px var(--mdd-transfer-accent); background: color-mix(in oklch, var(--mdd-transfer-accent) 6%, var(--mdd-transfer-panel)); }
}
.mdd-transfer-list {
  list-style: none;
  block-size: 100%;
  padding: 4px;
  overflow: auto;
  overscroll-behavior: contain;
  outline: none;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--mdd-transfer-ink) 20%, transparent) transparent;
}
.mdd-transfer-opt {
  position: relative;
  display: grid;
  grid-template-columns: 14px minmax(0, 1fr) auto;
  align-items: center;
  gap: 7px;
  block-size: 30px;
  padding: 0 7px;
  border-radius: 7px;
  cursor: grab;
  touch-action: none;
  transition: background-color .15s, opacity .2s;
  &:hover { background: color-mix(in oklch, var(--mdd-transfer-ink) 5%, transparent); }
  &[aria-selected="true"] { background: var(--mdd-transfer-sel); }
  &[data-active] { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mdd-transfer-ink) 30%, transparent); }
  .mdd-transfer-list:focus-visible &[data-active] { box-shadow: inset 0 0 0 1.5px var(--mdd-transfer-accent); }
  &[data-carried] { opacity: 0.28; background: transparent; box-shadow: none; outline: 1px dashed var(--mdd-transfer-faint); outline-offset: -1px; }
  &[data-new] { animation: mdd-transfer-flash 1s var(--mdd-transfer-out); }
  &[aria-disabled="true"] { cursor: default; & .mdd-transfer-name { color: var(--mdd-transfer-muted); } }
}
@keyframes mdd-transfer-flash { from { background: color-mix(in oklch, var(--mdd-transfer-accent) 34%, var(--mdd-transfer-panel)); } }
.mdd-transfer-tick {
  inline-size: 14px;
  block-size: 14px;
  border-radius: 4px;
  box-shadow: inset 0 0 0 1.5px var(--mdd-transfer-faint);
  display: grid;
  place-items: center;
  transition: background-color .15s, box-shadow .15s;
  & svg:not(.mdd-transfer-lock) { inline-size: 10px; block-size: 10px; fill: none; stroke: oklch(0.2 0.03 35); stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 12; stroke-dashoffset: 12; transition: stroke-dashoffset .25s var(--mdd-transfer-out); }
  [aria-selected="true"] > & { background: var(--mdd-transfer-accent); box-shadow: none; & svg:not(.mdd-transfer-lock) { stroke-dashoffset: 0; } }
  [aria-disabled="true"] > & { box-shadow: none; }
}
.mdd-transfer-lock { inline-size: 12px; block-size: 12px; fill: none; stroke: var(--mdd-transfer-faint); stroke-width: 1.5; }
.mdd-transfer-name { min-inline-size: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-weight: 520; }
.mdd-transfer-kind { font: 500 9.5px/1 var(--mdd-transfer-mono); color: var(--mdd-transfer-faint); letter-spacing: 0.02em; }
.mdd-transfer-empty {
  position: absolute;
  inset: 0;
  display: none;
  place-content: center;
  padding: 16px;
  text-align: center;
  font-size: 11.5px;
  color: var(--mdd-transfer-muted);
  text-wrap: balance;
  pointer-events: none;
  .mdd-transfer-box:not(:has(.mdd-transfer-opt:not([data-carried]))) > & { display: grid; }
}
.mdd-transfer-line {
  position: absolute;
  inset-inline: 8px;
  inset-block-start: 0;
  block-size: 2px;
  border-radius: 1px;
  background: var(--mdd-transfer-accent);
  translate: 0 var(--y, 0px);
  opacity: 0;
  pointer-events: none;
  transition: translate .18s var(--mdd-transfer-out), opacity .15s;
  &::before { content: ""; position: absolute; inset: -3px auto auto -4px; inline-size: 8px; block-size: 8px; border-radius: 50%; border: 2px solid var(--mdd-transfer-accent); background: var(--mdd-transfer-panel); }
  [data-line] & { opacity: 1; }
}

.mdd-transfer-ctrl {
  grid-area: ctrl;
  display: grid;
  align-content: center;
  gap: 8px;
}
.mdd-transfer-move {
  position: relative;
  display: grid;
  place-items: center;
