  padding: 0;
  border: 1px solid var(--mdd-transfer-line);
  border-radius: 9px;
  background: var(--mdd-transfer-panel);
  cursor: pointer;
  transition: background-color .2s, border-color .2s, color .2s, scale .2s var(--mdd-transfer-out), opacity .2s;
  & svg { inline-size: 16px; block-size: 16px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & b {
    position: absolute;
    inset: -6px -6px auto auto;
    min-inline-size: 17px;
    block-size: 17px;
    padding: 0 4px;
    border-radius: 999px;
    background: var(--mdd-transfer-accent);
    color: oklch(0.2 0.03 35);
    font: 700 10px/17px var(--mdd-transfer-mono);
    text-align: center;
    scale: 0;
    transition: scale .3s var(--mdd-transfer-spring);
  }
  &:not(:disabled) { border-color: color-mix(in oklch, var(--mdd-transfer-accent) 50%, transparent); color: var(--mdd-transfer-accent); & b { scale: 1; } }
  &:not(:disabled):hover { background: color-mix(in oklch, var(--mdd-transfer-accent) 14%, var(--mdd-transfer-panel)); }
  &:active:not(:disabled) { scale: 0.92; }
  &:disabled { opacity: 0.35; cursor: default; }
}

/* ---------- preview ---------- */
.mdd-transfer-preview {
  grid-area: preview;
  position: relative;
  border-radius: 10px;
  overflow: hidden;
  box-shadow: inset 0 0 0 1px var(--mdd-transfer-line);
}
.mdd-transfer-strip {
  overflow-x: auto;
  scrollbar-width: none;
