  [data-row="h"] > & { font-size: 10px; font-weight: 650; letter-spacing: 0.06em; text-transform: uppercase; color: var(--mdd-transfer-muted); }
  [data-row="v"] > & { font-family: var(--mdd-transfer-mono); font-size: 11px; font-variant-numeric: tabular-nums; }
  &[data-num] { text-align: end; }
  & + & { box-shadow: inset 1px 0 var(--mdd-transfer-line); }
  &[data-new] { animation: mdd-transfer-cell .5s var(--mdd-transfer-out); }
}
@keyframes mdd-transfer-cell { from { background: color-mix(in oklch, var(--mdd-transfer-accent) 22%, transparent); clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
.mdd-transfer-status {
  display: inline-block;
  padding: 1px 6px;
  border-radius: 999px;
  font-family: system-ui, sans-serif;
  font-size: 10.5px;
  font-weight: 600;
  background: color-mix(in oklch, oklch(0.78 0.12 230) 18%, transparent);
  color: oklch(0.85 0.08 230);
}

.mdd-transfer-hint {
  grid-area: hint;
  font-size: 11px;
  color: var(--mdd-transfer-muted);
  text-wrap: pretty;
  line-height: 1.6;
  & kbd {
    display: inline-block;
    min-inline-size: 18px;
    padding: 0 4px;
    border-radius: 4px;
    box-shadow: inset 0 0 0 1px var(--mdd-transfer-line), inset 0 -1px 0 var(--mdd-transfer-line);
    font: 500 10px/16px var(--mdd-transfer-mono);
    text-align: center;
    color: var(--mdd-transfer-ink);
  }
}

/* ---------- carried stack + flying clones ---------- */
.mdd-transfer-stack {
  position: absolute;
  inset: 0 auto auto 0;
  z-index: 10;
  display: none;
  inline-size: 150px;
  block-size: 30px;
  pointer-events: none;
  translate: var(--x, 0px) var(--y, 0px);
  [data-dragging] > & { display: block; }
}
.mdd-transfer-card {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 10px;
  border-radius: 8px;
  background: color-mix(in oklch, var(--mdd-transfer-accent) 30%, var(--mdd-transfer-panel));
  box-shadow: 0 0 0 1px color-mix(in oklch, var(--mdd-transfer-accent) 55%, transparent), 0 14px 26px -10px oklch(0 0 0 / 0.7);
  font-weight: 560;
  white-space: nowrap;
  overflow: hidden;
  rotate: calc(var(--k, 0) * -2.4deg);
  translate: calc(var(--k, 0) * 4px) calc(var(--k, 0) * 4px);
  transition: rotate .35s var(--mdd-transfer-spring), translate .35s var(--mdd-transfer-spring), opacity .2s;
  &:nth-child(1) { --k: 0; z-index: 3; }
  &:nth-child(2) { --k: 1; z-index: 2; }
  &:nth-child(3) { --k: 2; z-index: 1; }
  &[hidden] { display: none; }
  .mdd-transfer-stack[data-over] & { rotate: calc(var(--k, 0) * -1deg); }
}
.mdd-transfer-badge {
  position: absolute;
  inset: -8px -8px auto auto;
  z-index: 4;
  min-inline-size: 20px;
  block-size: 20px;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--mdd-transfer-accent);
  color: oklch(0.2 0.03 35);
  font: 700 11px/20px var(--mdd-transfer-mono);
  text-align: center;
  box-shadow: 0 0 0 2px var(--mdd-transfer-bg);
  &:empty { display: none; }
}
.mdd-transfer-fly {
  position: absolute;
  z-index: 9;
  margin: 0;
  pointer-events: none;
  list-style: none;
  background: var(--mdd-transfer-sel);
  box-shadow: 0 8px 18px -8px oklch(0 0 0 / 0.6);
}

.mdd-transfer-sr {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

@container (width < 330px) {
  .mdd-transfer-body {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    grid-template-rows: auto 1fr auto;
    grid-template-areas: "a b" "a b" "ctrl ctrl";
    row-gap: 8px;
  }
  .mdd-transfer-ctrl { grid-auto-flow: column; justify-content: center; gap: 12px; & .mdd-transfer-move { inline-size: 56px; } }
  .mdd-transfer-move[data-to="shown"] svg { rotate: 0deg; }
  .mdd-transfer-kind { display: none; }
  .mdd-transfer-opt { grid-template-columns: 14px minmax(0, 1fr); }
  .mdd-transfer-box { block-size: 206px; }
}

@media (prefers-reduced-motion: reduce) {
  .mdd-transfer-card, .mdd-transfer-move b, .mdd-transfer-line, .mdd-transfer-tick svg { transition: opacity .2s; }
  .mdd-transfer-card { rotate: 0deg; translate: calc(var(--k, 0) * 3px) calc(var(--k, 0) * 3px); }
  .mdd-transfer-opt[data-new], .mdd-transfer-cell[data-new] { animation: none; }
}

