const SPRING = "linear(0, 0.046, 0.156, 0.297, 0.446, 0.588, 0.712, 0.815, 0.896, 0.957, 0.998, 1.025, 1.039, 1.045, 1.045, 1.041, 1.035, 1.029, 1.022, 1.016, 1.011, 1.006, 1.003, 1.001, 0.999, 0.998, 1)";
const COLS = [
  { id: "tracking", t: "Tracking #", v: "TF-48213", k: "id", w: 92, lock: true },
  { id: "status", t: "Status", v: "In transit", k: "enum", w: 96, pill: true },
  { id: "carrier", t: "Carrier", v: "Bluegill Haul", k: "text", w: 112 },
  { id: "origin", t: "Origin", v: "Tacoma, WA", k: "text", w: 96 },
  { id: "dest", t: "Destination", v: "Boise, ID", k: "text", w: 96 },
  { id: "eta", t: "ETA", v: "Oct 4", k: "date", w: 70 },
  { id: "weight", t: "Weight", v: "1,240 kg", k: "num", w: 80, num: true },
  { id: "pallets", t: "Pallets", v: "3", k: "num", w: 66, num: true },
  { id: "cost", t: "Cost", v: "$1,982", k: "num", w: 74, num: true },
  { id: "customer", t: "Customer", v: "Harrow Mills", k: "text", w: 104 },
  { id: "created", t: "Created", v: "Sep 29", k: "date", w: 74 },
  { id: "updated", t: "Updated", v: "2 h ago", k: "date", w: 76 }
