const DEFAULT = ["tracking", "status", "carrier", "dest", "eta"];
const byId = Object.fromEntries(COLS.map((c) => [c.id, c]));
const $ = (s) => root.querySelector(s);
const lists = { avail: $('ul[data-list="avail"]'), shown: $('ul[data-list="shown"]') };
const cols = { avail: $('.mdd-transfer-col[data-list="avail"]'), shown: $('.mdd-transfer-col[data-list="shown"]') };
const moveBtn = { shown: $('.mdd-transfer-move[data-to="shown"]'), avail: $('.mdd-transfer-move[data-to="avail"]') };
const resetBtn = $(".mdd-transfer-reset");
const stack = $(".mdd-transfer-stack");
const cardsEl = [...stack.querySelectorAll(".mdd-transfer-card")];
const badge = $(".mdd-transfer-badge");
const rowH = $('[data-row="h"]'), rowV = $('[data-row="v"]');
const live = $(".mdd-transfer-sr");
const reduce = () => matchMedia("(prefers-reduced-motion: reduce)").matches;
const uid = "mdd-transfer-" + Math.random().toString(36).slice(2, 8);
const say = (m) => { live.textContent = ""; requestAnimationFrame(() => { if (!root.isConnected) return; live.textContent = m; }); };
for (const k of ["avail", "shown"]) {
