let drag = null;

/* ---------- build ---------- */
const TICK = '<span class="mdd-transfer-tick" aria-hidden="true"><svg viewBox="0 0 10 10"><path d="M2 5.2 4.2 7.3 8 3"/></svg></span>';
const LOCK = '<svg class="mdd-transfer-lock" viewBox="0 0 12 12" aria-hidden="true"><rect x="2.5" y="5.5" width="7" height="5" rx="1"/><path d="M4 5.5V4a2 2 0 0 1 4 0v1.5"/></svg>';
const KIND = { id: "id", enum: "enum", text: "abc", date: "date", num: "123" };
const opt = {}, hcell = {}, vcell = {};
for (const c of COLS) {
  const li = document.createElement("li");
  li.className = "mdd-transfer-opt";
  li.id = uid + "-" + c.id;
  li.dataset.id = c.id;
  li.setAttribute("role", "option");
  li.setAttribute("aria-selected", "false");
