  li.innerHTML = (c.lock ? '<span class="mdd-transfer-tick" aria-hidden="true">' + LOCK + "</span>" : TICK) + '<span class="mdd-transfer-name"></span><span class="mdd-transfer-kind" aria-hidden="true">' + KIND[c.k] + "</span>";
  li.querySelector(".mdd-transfer-name").textContent = c.t;
  if (c.lock) li.title = "Tracking # is always shown";
  opt[c.id] = li;
  const h = document.createElement("span");
  h.className = "mdd-transfer-cell";
  h.style.setProperty("--w", c.w + "px");
  h.textContent = c.t;
  const v = document.createElement("span");
  v.className = "mdd-transfer-cell";
  v.style.setProperty("--w", c.w + "px");
