const avail = () => COLS.map((c) => c.id).filter((id) => !shown.includes(id));
const listOf = (id) => (shown.includes(id) ? "shown" : "avail");
const ids = (k) => (k === "shown" ? shown : avail());

/* ---------- render ---------- */
function place() {
  for (const k of ["avail", "shown"]) for (const id of ids(k)) lists[k].append(opt[id]);
  for (const id of shown) { rowH.append(hcell[id]); rowV.append(vcell[id]); }
  for (const id of avail()) { hcell[id].remove(); vcell[id].remove(); }
}
function paintSel() {
  for (const k of ["avail", "shown"]) {
