  mutate();
  place();
  if (fresh && fresh.length) {
    const k = listOf(fresh[0]);
    const L = lists[k];
    const r = opt[fresh[0]].offsetTop, b = opt[fresh[fresh.length - 1]].offsetTop + 30;
    if (r < L.scrollTop || b > L.scrollTop + L.clientHeight) L.scrollTop = Math.max(0, r - 8);
    for (const id of fresh) { opt[id].removeAttribute("data-new"); opt[id].offsetWidth; opt[id].setAttribute("data-new", ""); }
    for (const id of fresh) if (shown.includes(id) && !hb.has(id)) { hcell[id].dataset.new = ""; vcell[id].dataset.new = ""; setTimeout(() => { delete hcell[id].dataset.new; delete vcell[id].dataset.new; }, 600); }
  }
  paintSel();
  if (reduce()) return;
  const rr = root.getBoundingClientRect();
  let n = 0;
  for (const c of COLS) {
    const el = opt[c.id];
    const b = el.getBoundingClientRect();
    const was = before.get(c.id);
    const src = from && from.has(c.id) ? from.get(c.id) : was.r;
    const crossed = was.k !== listOf(c.id) || (from && from.has(c.id));
    if (crossed) {
      const cl = el.cloneNode(true);
      cl.removeAttribute("id");
      cl.removeAttribute("data-new");
      cl.removeAttribute("data-carried");
      cl.classList.add("mdd-transfer-fly");
      cl.style.left = src.left - rr.left + "px";
      cl.style.top = src.top - rr.top + "px";
      cl.style.width = b.width + "px";
      root.append(cl);
      el.style.opacity = "0";
      const a = cl.animate([{ transform: "none" }, { transform: "translate(" + (b.left - src.left) + "px," + (b.top - src.top) + "px)" }],
        { duration: 460, delay: n++ * 45, easing: SPRING, fill: "both" });
      a.finished.then(() => { cl.remove(); el.style.opacity = ""; }, () => { cl.remove(); el.style.opacity = ""; });
    } else {
      const dy = src.top - b.top;
      if (Math.abs(dy) > 0.5) el.animate([{ transform: "translateY(" + dy + "px)" }, { transform: "none" }], { duration: 360, easing: SPRING });
    }
  }
  for (const id of shown) {
    const a = hb.get(id);
    if (!a) continue;
    const dx = a.left - hcell[id].getBoundingClientRect().left;
    if (Math.abs(dx) > 0.5) for (const el of [hcell[id], vcell[id]]) el.animate([{ transform: "translateX(" + dx + "px)" }, { transform: "none" }], { duration: 380, easing: SPRING });
