}

/* ---------- moving ---------- */
function ordered(k, set) { return ids(k).filter((id) => set.has(id) && !byId[id].lock); }
function moveTo(to, moving, index, from) {
  if (!moving.length) return;
  const fromK = listOf(moving[0]);
  relayout(() => {
    if (to === "shown") {
      const rest = shown.filter((id) => !moving.includes(id));
      let i = index == null ? rest.length : index;
      i = Math.max(1, Math.min(i, rest.length));
      shown = [...rest.slice(0, i), ...moving, ...rest.slice(i)];
    } else shown = shown.filter((id) => !moving.includes(id));
    sel.avail.clear(); sel.shown.clear();
    for (const id of moving) sel[to].add(id);
    active[to] = moving[0];
    anchor[to] = moving[0];
  }, from, moving);
  const n = moving.length;
  const names = n === 1 ? byId[moving[0]].t : n + " columns";
  if (to === fromK) say("Moved " + names + " to position " + (shown.indexOf(moving[0]) + 1) + " of " + shown.length + ".");
  else say((to === "shown" ? "Showing " : "Hid ") + names + ". " + shown.length + " columns shown.");
}
moveBtn.shown.addEventListener("click", () => { moveTo("shown", ordered("avail", sel.avail)); lists.shown.focus({ preventScroll: true }); });
moveBtn.avail.addEventListener("click", () => { moveTo("avail", ordered("shown", sel.shown)); lists.avail.focus({ preventScroll: true }); });
resetBtn.addEventListener("click", () => {
  const added = DEFAULT.filter((id) => !shown.includes(id));
  relayout(() => { shown = DEFAULT.slice(); sel.avail.clear(); sel.shown.clear(); }, null, added);
  say("Columns reset to default.");
});

/* ---------- selection ---------- */
function choose(k, id, mode) {
  if (byId[id].lock) { active[k] = id; paintSel(); say("Tracking # is always shown and stays first."); return; }
  const S = sel[k];
  if (mode === "toggle") { S.has(id) ? S.delete(id) : S.add(id); anchor[k] = id; }
  else if (mode === "range" && anchor[k] && listOf(anchor[k]) === k) {
