    const [a, b] = [L.indexOf(anchor[k]), L.indexOf(id)].sort((x, y) => x - y);
    S.clear();
    for (const x of L.slice(a, b + 1)) if (!byId[x].lock) S.add(x);
  } else { S.clear(); S.add(id); anchor[k] = id; }
  const other = k === "avail" ? "shown" : "avail";
  sel[other].clear();
  active[k] = id;
  paintSel();
}

/* ---------- pointer: select, then drag the whole selection ---------- */
for (const k of ["avail", "shown"]) {
  const L = lists[k];
  L.addEventListener("pointerdown", (e) => {
    const li = e.target.closest(".mdd-transfer-opt");
    if (!li || e.button !== 0 || drag) return;
    const id = li.dataset.id;
    const mod = e.metaKey || e.ctrlKey ? "toggle" : e.shiftKey ? "range" : null;
    if (mod) { choose(k, id, mod); return; }
    const wasSel = sel[k].has(id);
    if (!wasSel) choose(k, id, null);
    if (byId[id].lock) return;
