function lift(k, id, ev) {
  const moving = ordered(k, sel[k]);
  const rr = root.getBoundingClientRect();
  const from = new Map(moving.map((m) => [m, opt[m].getBoundingClientRect()]));
  const top = opt[id].getBoundingClientRect();
  drag = { k, id, moving, cx: ev.clientX, cy: ev.clientY, ox: ev.clientX - top.left, oy: ev.clientY - top.top, to: null, index: null };
  const order = [id, ...moving.filter((m) => m !== id)];
  cardsEl.forEach((c, i) => {
    c.hidden = i >= order.length;
    c.textContent = order[i] ? byId[order[i]].t : "";
  });
