  stack.style.width = top.width + "px";
  root.setAttribute("data-dragging", "");
  for (const m of moving) opt[m].setAttribute("data-carried", "");
  position();
  if (!reduce()) {
    const sx = drag.cx - rr.left - drag.ox, sy = drag.cy - rr.top - drag.oy;
    let n = 0;
    for (const m of moving) {
      if (m === id) continue;
      const a = from.get(m);
      const cl = opt[m].cloneNode(true);
      cl.removeAttribute("id");
      cl.removeAttribute("data-carried");
      cl.classList.add("mdd-transfer-fly");
      cl.style.left = a.left - rr.left + "px";
      cl.style.top = a.top - rr.top + "px";
      cl.style.width = a.width + "px";
      root.append(cl);
      cl.animate([{ transform: "none", opacity: 1 }, { transform: "translate(" + (sx - (a.left - rr.left)) + "px," + (sy - (a.top - rr.top)) + "px) scale(.92)", opacity: 0 }],
