  drag.to = to;
  for (const k of ["avail", "shown"]) cols[k].toggleAttribute("data-target", to === k && (k !== drag.k || k === "shown"));
  stack.toggleAttribute("data-over", !!to);
  const box = cols.shown.querySelector(".mdd-transfer-box");
  box.toggleAttribute("data-line", to === "shown");
  if (to !== "shown") { drag.index = null; return; }
  const L = lists.shown;
  const rest = shown.filter((id) => !drag.moving.includes(id));
  let i = rest.length;
  for (let j = 0; j < rest.length; j++) {
    const r = opt[rest[j]].getBoundingClientRect();
    if (drag.cy < r.top + r.height / 2) { i = j; break; }
  }
