}
function autoScroll() {
  if (!root.isConnected) return;
  if (!drag) return;
  for (const k of ["avail", "shown"]) {
    if (!over(k)) continue;
    const L = lists[k];
    const r = L.getBoundingClientRect();
    let v = 0;
    if (drag.cy < r.top + 28) v = -6; else if (drag.cy > r.bottom - 28) v = 6;
    if (v) { const b = L.scrollTop; L.scrollTop = b + v; if (L.scrollTop !== b) track(); }
  }
