  root.removeAttribute("data-dragging");
  for (const k of ["avail", "shown"]) cols[k].removeAttribute("data-target");
  cols.shown.querySelector(".mdd-transfer-box").removeAttribute("data-line");
  for (const m of d.moving) opt[m].removeAttribute("data-carried");
  const to = cancel ? null : d.to;
  const from = new Map(d.moving.map((m, i) => [m, new DOMRect(sr.left + i * 3, sr.top + i * 3, sr.width, sr.height)]));
  if (to === "shown") moveTo("shown", d.moving, d.index, from);
  else if (to === "avail" && d.k === "shown") moveTo("avail", d.moving, null, from);
  else {
    relayout(() => {}, from, []);
