}
root.addEventListener("keydown", (e) => { if (e.key === "Escape" && drag) { e.preventDefault(); drop(true); } });

/* ---------- keyboard (listbox pattern) ---------- */
for (const k of ["avail", "shown"]) {
  const L = lists[k];
  L.addEventListener("focus", () => {
    if (!active[k] && ids(k).length) { active[k] = ids(k)[0]; paintSel(); }
  });
  L.addEventListener("keydown", (e) => {
    if (drag) return;
    const list = ids(k);
    if (!list.length) return;
    let i = Math.max(0, list.indexOf(active[k]));
    const key = e.key;
    const mod = e.metaKey || e.ctrlKey;
    if ((key === "ArrowUp" || key === "ArrowDown") && e.altKey && k === "shown") {
      e.preventDefault();
      const moving = ordered("shown", sel.shown.size ? sel.shown : new Set([active[k]]));
      if (!moving.length) return;
      const rest = shown.filter((id) => !moving.includes(id));
      const first = shown.indexOf(moving[0]);
      const idx = Math.max(1, Math.min(rest.length, first + (key === "ArrowUp" ? -1 : 1)));
      if (idx === first) return;
      moveTo("shown", moving, idx);
      active.shown = moving[0];
      paintSel();
      return;
    }
    if (key === "ArrowUp" || key === "ArrowDown" || key === "Home" || key === "End") {
      e.preventDefault();
      const j = key === "Home" ? 0 : key === "End" ? list.length - 1 : Math.max(0, Math.min(list.length - 1, i + (key === "ArrowUp" ? -1 : 1)));
      active[k] = list[j];
      if (e.shiftKey && !byId[list[j]].lock) { sel[k].add(list[j]); if (!byId[list[i]].lock) sel[k].add(list[i]); }
      paintSel();
      opt[list[j]].scrollIntoView({ block: "nearest" });
    } else if (key === " ") {
      e.preventDefault();
      choose(k, active[k] || list[0], "toggle");
    } else if (key === "Enter") {
      e.preventDefault();
      const set = sel[k].size ? sel[k] : new Set([active[k]]);
      const moving = ordered(k, set);
      if (!moving.length) { say(k === "shown" ? "Tracking # is always shown." : "Nothing selected."); return; }
      const next = list.find((id, j) => j > i && !moving.includes(id)) || list.slice().reverse().find((id) => !moving.includes(id)) || null;
      moveTo(k === "avail" ? "shown" : "avail", moving);
      active[k] = next;
      paintSel();
      L.focus();
    } else if (key === "a" && mod) {
      e.preventDefault();
      sel[k] = new Set(list.filter((id) => !byId[id].lock));
      paintSel();
      say(sel[k].size + " selected.");
    } else if (key === "Escape") {
      if (sel[k].size) { e.preventDefault(); sel[k].clear(); paintSel(); say("Selection cleared."); }
    }
  });
}

place();
paintSel();

