@property --mdd-dropzone-p { syntax: "<number>"; inherits: true; initial-value: 0; }
@property --mdd-dropzone-fade { syntax: "<length>"; inherits: false; initial-value: 0px; }
@property --mdd-dropzone-edge { syntax: "<length>"; inherits: false; initial-value: 0px; }

.mdd-dropzone {
  --mdd-dropzone-paper: oklch(0.988 0.003 250);
  --mdd-dropzone-ink: oklch(0.25 0.03 262);
  --mdd-dropzone-accent: oklch(0.53 0.19 262);
  --mdd-dropzone-danger: oklch(0.57 0.2 27);
  --mdd-dropzone-ok: oklch(0.6 0.14 158);
  --mdd-dropzone-line: color-mix(in oklch, var(--mdd-dropzone-ink) 12%, transparent);
  --mdd-dropzone-muted: color-mix(in oklch, var(--mdd-dropzone-ink) 58%, var(--mdd-dropzone-paper));
  --mdd-dropzone-tint: color-mix(in oklch, var(--mdd-dropzone-accent) 7%, var(--mdd-dropzone-paper));
  --mdd-dropzone-sunk: color-mix(in oklch, var(--mdd-dropzone-ink) 3.5%, var(--mdd-dropzone-paper));
  --mdd-dropzone-tone: var(--mdd-dropzone-accent);
  --mdd-dropzone-spring: linear(0, 0.046, 0.156, 0.297, 0.446, 0.588, 0.712, 0.815, 0.896, 0.957, 0.998, 1.025, 1.039, 1.045, 1.045, 1.041, 1.035, 1.029, 1.022, 1.016, 1.011, 1.006, 1.003, 1.001, 0.999, 0.998, 1);
  --mdd-dropzone-out: cubic-bezier(.16, 1, .3, 1);
  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head" "zone" "files" "foot" "samples";
  gap: 12px;
  inline-size: 100%;
  max-inline-size: 440px;
  box-sizing: border-box;
  padding: 16px 16px 14px;
  border-radius: 18px;
  background: var(--mdd-dropzone-paper);
  color: var(--mdd-dropzone-ink);
  font: 400 13px/1.35 system-ui, -apple-system, "Segoe UI", sans-serif;
  box-shadow: 0 0 0 1px var(--mdd-dropzone-line), 0 22px 46px -26px oklch(0.3 0.06 262 / 0.45);
  accent-color: var(--mdd-dropzone-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(p, h3, ul) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; }
  & :focus-visible { outline: 2px solid var(--mdd-dropzone-accent); outline-offset: 2px; }
}

.mdd-dropzone-head {
  grid-area: head;
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-areas: "eyebrow eyebrow" "title rules";
  align-items: baseline;
  column-gap: 10px;
}
.mdd-dropzone-eyebrow {
  grid-area: eyebrow;
  font-size: 10.5px;
  font-weight: 650;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--mdd-dropzone-muted);
}
.mdd-dropzone-title {
  grid-area: title;
  font-size: clamp(18px, 6cqi, 22px);
  font-weight: 690;
  letter-spacing: -0.022em;
  line-height: 1.15;
  text-wrap: balance;
}
.mdd-dropzone-rules { grid-area: rules; font-size: 11px; color: var(--mdd-dropzone-muted); text-align: end; text-wrap: balance; }

/* ---------- the drop zone ---------- */
.mdd-dropzone-zone {
  grid-area: zone;
  position: relative;
  display: grid;
  justify-items: center;
  align-content: center;
  gap: 8px;
  min-block-size: 132px;
  padding: 18px 16px;
  border-radius: 14px;
  background: var(--mdd-dropzone-sunk);
  text-align: center;
  cursor: pointer;
  isolation: isolate;
  transition: background-color .25s, min-block-size .45s var(--mdd-dropzone-out), padding .45s var(--mdd-dropzone-out);
  &:hover { background: var(--mdd-dropzone-tint); }
  &:has(.mdd-dropzone-input:focus-visible) { outline: 2px solid var(--mdd-dropzone-accent); outline-offset: 3px; }
}
.mdd-dropzone-input {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  opacity: 0;
  pointer-events: none;
}
.mdd-dropzone-ring {
  position: absolute;
  inset: 0;
  inline-size: 100%;
  block-size: 100%;
  z-index: -1;
  overflow: visible;
  pointer-events: none;
  & rect {
    x: 1px;
    y: 1px;
    width: calc(100% - 2px);
    height: calc(100% - 2px);
    rx: 13px;
    fill: none;
    stroke: color-mix(in oklch, var(--mdd-dropzone-ink) 26%, transparent);
    stroke-width: 1.5px;
    stroke-dasharray: 7 6;
    transition: stroke .25s, stroke-width .25s;
  }
}
.mdd-dropzone-art {
  inline-size: 52px;
  block-size: 44px;
  overflow: visible;
  transition: scale .4s var(--mdd-dropzone-spring), inline-size .45s var(--mdd-dropzone-out), block-size .45s var(--mdd-dropzone-out);
  & path { stroke: var(--mdd-dropzone-tone); stroke-width: 1.6; stroke-linejoin: round; stroke-linecap: round; transition: stroke .25s; }
  & .mdd-dropzone-doc { fill: var(--mdd-dropzone-paper); transition: translate .5s var(--mdd-dropzone-spring), rotate .5s var(--mdd-dropzone-spring), stroke .25s; transform-origin: 25px 26px; }
  & .mdd-dropzone-tray { fill: color-mix(in oklch, var(--mdd-dropzone-tone) 12%, var(--mdd-dropzone-paper)); }
}
.mdd-dropzone-copy {
  display: grid;
  gap: 2px;
  & b { font-size: 14px; font-weight: 650; letter-spacing: -0.01em; }
  & [data-sub] { font-size: 12px; color: var(--mdd-dropzone-muted); text-wrap: balance; }
  & u { color: var(--mdd-dropzone-accent); font-weight: 600; text-decoration-thickness: 1px; text-underline-offset: 3px; }
}

/* armed: something is being dragged anywhere over the component */
.mdd-dropzone[data-drag] .mdd-dropzone-ring rect { stroke: color-mix(in oklch, var(--mdd-dropzone-accent) 60%, transparent); animation: mdd-dropzone-march 0.9s linear infinite; }
.mdd-dropzone[data-drag] .mdd-dropzone-doc { translate: 0 -3px; rotate: -4deg; }
@keyframes mdd-dropzone-march { to { stroke-dashoffset: -13; } }
/* over: the pointer is inside the zone */
.mdd-dropzone-zone[data-over] {
  background: color-mix(in oklch, var(--mdd-dropzone-tone) 9%, var(--mdd-dropzone-paper));
  & .mdd-dropzone-ring rect { stroke: var(--mdd-dropzone-tone); stroke-width: 2px; animation-duration: .45s; }
  & .mdd-dropzone-doc { translate: 0 7px; rotate: 0deg; }
  & .mdd-dropzone-art { scale: 1.06; }
}
.mdd-dropzone-zone[data-invalid] {
  --mdd-dropzone-tone: var(--mdd-dropzone-danger);
  & .mdd-dropzone-doc { translate: 0 -6px; rotate: 8deg; }
  & b { color: var(--mdd-dropzone-danger); }
}

/* once there are files, the zone steps back into a compact row */
.mdd-dropzone:has(.mdd-dropzone-file) .mdd-dropzone-zone {
  min-block-size: 64px;
  padding: 10px 14px;
  grid-auto-flow: column;
  justify-content: center;
  text-align: start;
  gap: 12px;
  & .mdd-dropzone-art { inline-size: 34px; block-size: 29px; }
}

/* ---------- file rows ---------- */
.mdd-dropzone-files {
  grid-area: files;
  list-style: none;
  display: grid;
  gap: 6px;
  max-block-size: 214px;
  overflow: auto;
  overscroll-behavior: contain;
  margin: -4px;
  padding: 4px;
  scrollbar-width: thin;
  mask: linear-gradient(#000 calc(100% - var(--mdd-dropzone-fade)), transparent);
  &:empty { display: none; }
}
.mdd-dropzone-file {
  --mdd-dropzone-tone: var(--mdd-dropzone-accent);
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr) auto;
  grid-template-areas: "icon name act" "icon meta act";
  align-items: center;
  column-gap: 10px;
  row-gap: 3px;
  padding: 8px 8px 8px 9px;
  border-radius: 11px;
  background: var(--mdd-dropzone-paper);
  box-shadow: 0 0 0 1px var(--mdd-dropzone-line), 0 1px 2px oklch(0.3 0.04 262 / 0.05);
  transition: box-shadow .25s, background-color .25s, opacity .3s, translate .45s var(--mdd-dropzone-spring);
  @starting-style { opacity: 0; translate: 0 -8px; }
  &[data-state="error"], &[data-state="rejected"] {
    --mdd-dropzone-tone: var(--mdd-dropzone-danger);
    background: color-mix(in oklch, var(--mdd-dropzone-danger) 6%, oklch(0.99 0.004 40));
    box-shadow: 0 0 0 1px color-mix(in oklch, var(--mdd-dropzone-danger) 30%, transparent);
  }
  &[data-state="done"] { --mdd-dropzone-tone: var(--mdd-dropzone-ok); }
}
.mdd-dropzone-ico {
  grid-area: icon;
  position: relative;
  inline-size: 30px;
  block-size: 34px;
  & svg { inline-size: 100%; block-size: 100%; overflow: visible; }
  & .mdd-dropzone-sheet { fill: var(--mdd-dropzone-paper); stroke: color-mix(in oklch, var(--mdd-dropzone-ink) 30%, transparent); stroke-width: 1.2; stroke-linejoin: round; }
  & .mdd-dropzone-band { fill: var(--mdd-dropzone-kind, var(--mdd-dropzone-accent)); }
  & text { font: 700 6.5px/1 ui-monospace, Menlo, monospace; fill: var(--mdd-dropzone-paper); letter-spacing: 0.04em; }
  &[data-kind="pdf"] { --mdd-dropzone-kind: oklch(0.58 0.19 27); }
  &[data-kind="png"] { --mdd-dropzone-kind: oklch(0.55 0.13 200); }
  &[data-kind="jpg"] { --mdd-dropzone-kind: oklch(0.62 0.14 75); }
  &[data-kind="other"] { --mdd-dropzone-kind: oklch(0.55 0.02 262); }
}
.mdd-dropzone-name {
  grid-area: name;
  min-inline-size: 0;
  font-size: 12.5px;
  font-weight: 580;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.mdd-dropzone-meta {
  grid-area: meta;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  min-inline-size: 0;
  font-size: 11px;
  color: var(--mdd-dropzone-muted);
  font-variant-numeric: tabular-nums;
  & span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  [data-state="error"] &, [data-state="rejected"] & { color: var(--mdd-dropzone-danger); }
}
.mdd-dropzone-bar {
  display: none;
  block-size: 4px;
  border-radius: 2px;
  background: color-mix(in oklch, var(--mdd-dropzone-ink) 9%, transparent);
  overflow: hidden;
  & i {
    display: block;
    block-size: 100%;
    inline-size: 100%;
    border-radius: inherit;
    background: var(--mdd-dropzone-tone);
    transform-origin: left;
    transform: scaleX(var(--mdd-dropzone-p));
  }
  [data-state="up"] &, [data-state="queued"] &, [data-state="error"] & { display: block; }
  [data-state="up"] & i { background: linear-gradient(90deg, var(--mdd-dropzone-tone) 0 60%, color-mix(in oklch, var(--mdd-dropzone-tone) 55%, white) 80%, var(--mdd-dropzone-tone) 100%) 0 0 / 200% 100%; animation: mdd-dropzone-sheen 1.1s linear infinite; }
}
@keyframes mdd-dropzone-sheen { from { background-position: 100% 0; } to { background-position: -100% 0; } }
.mdd-dropzone-act { grid-area: act; display: flex; align-items: center; gap: 4px; }
.mdd-dropzone-pct { font: 600 11px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--mdd-dropzone-tone); min-inline-size: 3.6ch; text-align: end; }
.mdd-dropzone-check {
  inline-size: 20px;
  block-size: 20px;
  & circle { fill: var(--mdd-dropzone-ok); }
  & path { fill: none; stroke: white; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 12; stroke-dashoffset: 12; animation: mdd-dropzone-tick .45s var(--mdd-dropzone-out) .1s forwards; }
}
@keyframes mdd-dropzone-tick { to { stroke-dashoffset: 0; } }
.mdd-dropzone-iconbtn, .mdd-dropzone-retry {
  display: inline-grid;
  place-items: center;
  block-size: 26px;
  min-inline-size: 26px;
  padding: 0;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--mdd-dropzone-muted);
  cursor: pointer;
  transition: background-color .2s, color .2s;
  & svg { inline-size: 14px; block-size: 14px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; }
  &:hover { background: color-mix(in oklch, var(--mdd-dropzone-ink) 7%, transparent); color: var(--mdd-dropzone-ink); }
}
.mdd-dropzone-retry { padding: 0 9px; font-size: 11.5px; font-weight: 600; color: var(--mdd-dropzone-danger); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mdd-dropzone-danger) 35%, transparent); &:hover { background: color-mix(in oklch, var(--mdd-dropzone-danger) 9%, transparent); color: var(--mdd-dropzone-danger); } }

/* ---------- footer ---------- */
.mdd-dropzone-foot {
  grid-area: foot;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas: "total submit" "meter submit";
  align-items: center;
  column-gap: 12px;
  row-gap: 5px;
}
.mdd-dropzone-total { grid-area: total; font-size: 12px; color: var(--mdd-dropzone-muted); font-variant-numeric: tabular-nums; & b { color: var(--mdd-dropzone-ink); font-weight: 650; } }
.mdd-dropzone-meter {
  grid-area: meter;
  display: block;
  block-size: 4px;
  border-radius: 2px;
  background: color-mix(in oklch, var(--mdd-dropzone-ink) 8%, transparent);
  overflow: hidden;
  & i { display: block; block-size: 100%; inline-size: calc(var(--used, 0) * 100%); border-radius: inherit; background: var(--mdd-dropzone-ink); transition: inline-size .5s var(--mdd-dropzone-out); }
}
.mdd-dropzone-submit {
  grid-area: submit;
  block-size: 34px;
  padding: 0 16px;
  border: 0;
  border-radius: 10px;
  background: var(--mdd-dropzone-accent);
  color: var(--mdd-dropzone-paper);
  font-size: 13px;
  font-weight: 650;
  cursor: pointer;
  transition: background-color .2s, scale .2s var(--mdd-dropzone-out), opacity .2s;
