  &:active:not(:disabled) { scale: 0.96; }
  &:disabled { background: color-mix(in oklch, var(--mdd-dropzone-ink) 10%, var(--mdd-dropzone-paper)); color: var(--mdd-dropzone-muted); cursor: default; }
  &[data-done] { background: var(--mdd-dropzone-ok); color: white; opacity: 1; }
}

/* ---------- sample files you can drag in ---------- */
.mdd-dropzone-samples {
  grid-area: samples;
  display: grid;
  gap: 7px;
  padding-block-start: 12px;
  border-block-start: 1px dashed var(--mdd-dropzone-line);
}
.mdd-dropzone-samples-label { font-size: 10.5px; font-weight: 650; letter-spacing: 0.1em; text-transform: uppercase; color: var(--mdd-dropzone-muted); & span { font-weight: 500; letter-spacing: 0.02em; text-transform: none; font-size: 11px; } }
.mdd-dropzone-chips {
  display: flex;
  gap: 6px;
  margin: -4px;
  padding: 4px;
  overflow-x: auto;
  scrollbar-width: none;
  mask: linear-gradient(90deg, #000 calc(100% - var(--mdd-dropzone-edge)), transparent);
}
@supports (animation-timeline: scroll()) {
  .mdd-dropzone-chips { animation: mdd-dropzone-edge linear both; animation-timeline: scroll(self inline); }
  .mdd-dropzone-files { animation: mdd-dropzone-fade linear both; animation-timeline: scroll(self block); }
}
@keyframes mdd-dropzone-edge { from { --mdd-dropzone-edge: 28px; } 90% { --mdd-dropzone-edge: 28px; } to { --mdd-dropzone-edge: 0px; } }
@keyframes mdd-dropzone-fade { from { --mdd-dropzone-fade: 22px; } 92% { --mdd-dropzone-fade: 22px; } to { --mdd-dropzone-fade: 0px; } }
.mdd-dropzone-chip {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-inline-size: 100%;
  block-size: 28px;
  padding: 0 9px 0 6px;
  border: 0;
  border-radius: 8px;
  background: var(--mdd-dropzone-paper);
  box-shadow: 0 0 0 1px var(--mdd-dropzone-line), 0 1px 2px oklch(0.3 0.04 262 / 0.07);
  font-size: 11.5px;
  font-weight: 560;
  cursor: grab;
  transition: box-shadow .2s, translate .3s var(--mdd-dropzone-spring), opacity .25s;
  &:hover:not(:disabled) { translate: 0 -2px; box-shadow: 0 0 0 1px color-mix(in oklch, var(--mdd-dropzone-accent) 45%, transparent), 0 6px 12px -6px oklch(0.3 0.08 262 / 0.35); }
  &:active { cursor: grabbing; }
  &:disabled { opacity: 0.4; cursor: default; box-shadow: 0 0 0 1px var(--mdd-dropzone-line); }
  & i { inline-size: 16px; block-size: 18px; flex: none; border-radius: 2px 5px 2px 2px; background: var(--mdd-dropzone-kind); position: relative; }
  & span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { font: 500 10px/1 ui-monospace, Menlo, monospace; color: var(--mdd-dropzone-muted); font-variant-numeric: tabular-nums; }
  &[data-kind="pdf"] { --mdd-dropzone-kind: oklch(0.58 0.19 27); }
  &[data-kind="png"] { --mdd-dropzone-kind: oklch(0.55 0.13 200); }
  &[data-kind="jpg"] { --mdd-dropzone-kind: oklch(0.62 0.14 75); }
  &[data-kind="other"] { --mdd-dropzone-kind: oklch(0.55 0.02 262); }
  &[data-dragging] { opacity: 0.35; }
}

.mdd-dropzone-sr {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

@container (width < 340px) {
  .mdd-dropzone-head { grid-template-areas: "eyebrow eyebrow" "title title" "rules rules"; }
  .mdd-dropzone-rules { text-align: start; }
  .mdd-dropzone-chip small { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .mdd-dropzone-zone, .mdd-dropzone-art, .mdd-dropzone-file, .mdd-dropzone-chip, .mdd-dropzone-meter i { transition: background-color .2s, opacity .2s, box-shadow .2s; }
  .mdd-dropzone-art .mdd-dropzone-doc { transition: none; translate: none !important; rotate: none !important; }
  .mdd-dropzone[data-drag] .mdd-dropzone-ring rect { animation: none; }
  .mdd-dropzone-bar i { animation: none !important; }
  .mdd-dropzone-check path { animation: none; stroke-dashoffset: 0; }
  .mdd-dropzone-file { @starting-style { opacity: 0; translate: none; } }
  .mdd-dropzone-chip:hover:not(:disabled) { translate: none; }
}

