const MB = 1e6;
const LIMIT = 10 * MB, MAX_FILES = 5, MAX_TOTAL = 25 * MB;
const MIME = { pdf: "application/pdf", png: "image/png", jpg: "image/jpeg" };
const SAMPLES = [
  { id: "taxi", name: "taxi-aeroporto.jpg", size: 1.2 * MB },
  { id: "hotel", name: "hotel-alfama-folio.pdf", size: 3.4 * MB },
  { id: "dinner", name: "dinner-taberna.png", size: 0.8 * MB, flaky: true },
  { id: "flight", name: "flight-itinerary.pdf", size: 12.6 * MB },
  { id: "photo", name: "team-photo.heic", size: 2.1 * MB }
];
const $ = (s) => root.querySelector(s);
const zone = $(".mdd-dropzone-zone");
const input = $(".mdd-dropzone-input");
const list = $(".mdd-dropzone-files");
const title = zone.querySelector("[data-title]");
const sub = zone.querySelector("[data-sub]");
const totalEl = $("[data-total]");
