@property --mdd-mapper-p { syntax: "<percentage>"; inherits: false; initial-value: 0%; }

.mdd-mapper {
  --mdd-mapper-bg: oklch(0.19 0.014 168);
  --mdd-mapper-panel: oklch(0.232 0.016 168);
  --mdd-mapper-ink: oklch(0.95 0.012 140);
  --mdd-mapper-accent: oklch(0.86 0.13 163);
  --mdd-mapper-danger: oklch(0.72 0.17 25);
  --mdd-mapper-line: color-mix(in oklch, var(--mdd-mapper-ink) 11%, transparent);
  --mdd-mapper-muted: color-mix(in oklch, var(--mdd-mapper-ink) 56%, var(--mdd-mapper-bg));
  --mdd-mapper-faint: color-mix(in oklch, var(--mdd-mapper-ink) 30%, var(--mdd-mapper-bg));
  --mdd-mapper-mono: ui-monospace, Menlo, monospace;
  --mdd-mapper-spring: linear(0, 0.046, 0.156, 0.297, 0.446, 0.588, 0.712, 0.815, 0.896, 0.957, 0.998, 1.025, 1.039, 1.045, 1.045, 1.041, 1.035, 1.029, 1.022, 1.016, 1.011, 1.006, 1.003, 1.001, 0.999, 0.998, 1);
  --mdd-mapper-out: cubic-bezier(.16, 1, .3, 1);
  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head" "board" "foot";
  gap: 14px;
  inline-size: 100%;
  max-inline-size: 480px;
  box-sizing: border-box;
  padding: 16px 14px 14px;
  border-radius: 16px;
  background:
    radial-gradient(120% 60% at 50% 0%, color-mix(in oklch, var(--mdd-mapper-accent) 6%, transparent), transparent 70%),
    var(--mdd-mapper-bg);
  color: var(--mdd-mapper-ink);
  font: 400 12.5px/1.35 system-ui, -apple-system, "Segoe UI", sans-serif;
  box-shadow: 0 0 0 1px var(--mdd-mapper-line), 0 26px 50px -28px oklch(0 0 0 / 0.85);
  accent-color: var(--mdd-mapper-accent);
  -webkit-user-select: none;
  user-select: none;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(p, h3, ul, ol) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; }
  & :focus-visible { outline: 2px solid var(--mdd-mapper-accent); outline-offset: 2px; }
}

/* type hues drive glyphs, ports and wires */
.mdd-mapper [data-type="text"] { --mdd-mapper-h: 80; }
.mdd-mapper [data-type="email"] { --mdd-mapper-h: 32; }
.mdd-mapper [data-type="phone"] { --mdd-mapper-h: 165; }
.mdd-mapper [data-type="date"] { --mdd-mapper-h: 250; }
.mdd-mapper [data-type="number"] { --mdd-mapper-h: 118; }
.mdd-mapper [data-type="enum"] { --mdd-mapper-h: 330; }

.mdd-mapper-head {
  grid-area: head;
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-areas: "eyebrow eyebrow" "title title" "status status" "meter meter";
  row-gap: 3px;
}
.mdd-mapper-eyebrow {
  grid-area: eyebrow;
  display: flex;
  align-items: center;
  gap: 5px;
  font: 500 11px/1.2 var(--mdd-mapper-mono);
  color: var(--mdd-mapper-muted);
  & svg { inline-size: 13px; block-size: 13px; fill: none; stroke: currentColor; stroke-width: 1.3; stroke-linejoin: round; }
}
.mdd-mapper-title {
  grid-area: title;
  font-size: clamp(17px, 5.6cqi, 21px);
  font-weight: 680;
  letter-spacing: -0.02em;
  line-height: 1.15;
  text-wrap: balance;
}
.mdd-mapper-status {
  grid-area: status;
  display: flex;
  flex-wrap: wrap;
  gap: 2px 10px;
  margin-block-start: 3px;
  font-size: 11.5px;
  color: var(--mdd-mapper-muted);
  font-variant-numeric: tabular-nums;
  & [data-req] { color: oklch(0.84 0.12 75); }
  & [data-req]:empty { display: none; }
  & [data-req][data-ok] { color: var(--mdd-mapper-accent); }
}
.mdd-mapper-meter {
  grid-area: meter;
  list-style: none;
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 1fr;
  gap: 3px;
  margin-block-start: 7px;
  & li {
    block-size: 3px;
    border-radius: 2px;
    background: color-mix(in oklch, var(--mdd-mapper-ink) 10%, transparent);
    transition: background-color .4s;
    &[data-on] { background: oklch(0.8 0.12 var(--mdd-mapper-h)); }
  }
}

/* ---------- board ---------- */
.mdd-mapper-board {
  grid-area: board;
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) clamp(34px, 15cqi, 70px) minmax(0, 1fr);
  grid-template-areas: "lsrc . ldst" "src . dst";
  row-gap: 7px;
}
.mdd-mapper-col-label {
  font-size: 10.5px;
  font-weight: 650;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--mdd-mapper-faint);
  &[data-side="src"] { grid-area: lsrc; }
  &[data-side="dst"] { grid-area: ldst; }
}
.mdd-mapper-src, .mdd-mapper-dst { list-style: none; display: grid; gap: 6px; }
.mdd-mapper-src { grid-area: src; }
.mdd-mapper-dst { grid-area: dst; }

.mdd-mapper-glyph {
  display: grid;
  place-items: center;
  inline-size: 22px;
  block-size: 22px;
  flex: none;
  border-radius: 6px;
  background: oklch(0.8 0.12 var(--mdd-mapper-h) / 0.14);
  color: oklch(0.84 0.11 var(--mdd-mapper-h));
  & svg { inline-size: 13px; block-size: 13px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
}
.mdd-mapper-s, .mdd-mapper-dbtn {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  grid-template-areas: "g name" "g sub";
  align-items: center;
  column-gap: 8px;
  inline-size: 100%;
  block-size: 42px;
  padding: 0 10px 0 8px;
  border: 0;
  border-radius: 10px;
  background: var(--mdd-mapper-panel);
  box-shadow: inset 0 0 0 1px var(--mdd-mapper-line);
  text-align: start;
  transition: box-shadow .2s, background-color .2s, opacity .25s, scale .3s var(--mdd-mapper-spring);
  & .mdd-mapper-glyph { grid-area: g; }
}
.mdd-mapper-s {
  position: relative;
  cursor: grab;
  touch-action: none;
  &:hover { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mdd-mapper-ink) 24%, transparent); }
  &[data-linked] { background: color-mix(in oklch, oklch(0.8 0.12 var(--mdd-mapper-h)) 7%, var(--mdd-mapper-panel)); }
  &[data-source] { box-shadow: inset 0 0 0 1.5px oklch(0.8 0.12 var(--mdd-mapper-h)); cursor: grabbing; }
}
.mdd-mapper-name {
  grid-area: name;
  min-inline-size: 0;
  font-weight: 580;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  align-self: end;
  & b { color: oklch(0.84 0.12 75); font-weight: 700; margin-inline-start: 2px; }
}
.mdd-mapper-sample, .mdd-mapper-val {
  grid-area: sub;
  min-inline-size: 0;
  align-self: start;
  font: 400 10.5px/1.3 var(--mdd-mapper-mono);
  color: var(--mdd-mapper-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.mdd-mapper-port {
  position: absolute;
  inset-block-start: 50%;
  z-index: 2;
  inline-size: 11px;
  block-size: 11px;
  margin-block-start: -5.5px;
  border-radius: 50%;
  background: var(--mdd-mapper-bg);
  box-shadow: inset 0 0 0 2px oklch(0.8 0.12 var(--mdd-mapper-h, 160));
  transition: scale .3s var(--mdd-mapper-spring), box-shadow .2s, background-color .2s;
  .mdd-mapper-s & { inset-inline-end: -5.5px; }
  .mdd-mapper-d & { inset-inline-start: -5.5px; box-shadow: inset 0 0 0 2px var(--mdd-mapper-faint); }
  [data-linked] > & { background: oklch(0.8 0.12 var(--mdd-mapper-h, 160)); }
  .mdd-mapper-s:hover > & { scale: 1.3; }
}

.mdd-mapper-d {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
}
.mdd-mapper-dbtn {
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas: "name g" "sub g";
  padding: 0 8px 0 12px;
  cursor: default;
  grid-column: 1 / -1;
  grid-row: 1;
  .mdd-mapper-d[data-linked] & { background: color-mix(in oklch, oklch(0.8 0.12 var(--mdd-mapper-h)) 8%, var(--mdd-mapper-panel)); }
  .mdd-mapper-d[data-linked] & .mdd-mapper-val { color: oklch(0.88 0.06 var(--mdd-mapper-h)); }
  .mdd-mapper-d[data-skip] & .mdd-mapper-val { font-style: italic; }
}
.mdd-mapper-d[data-linked] { --mdd-mapper-h: var(--mdd-mapper-link-h); }
/* a field is clickable: it opens its column chooser */
.mdd-mapper:not([data-connecting], [data-done]) {
  & .mdd-mapper-dbtn { cursor: pointer; }
  & .mdd-mapper-d:hover > .mdd-mapper-port { scale: 1.3; }
  & .mdd-mapper-d:not([data-req]):hover .mdd-mapper-dbtn:not([aria-expanded="true"]) { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mdd-mapper-ink) 24%, transparent); }
}
.mdd-mapper .mdd-mapper-d[data-id] .mdd-mapper-dbtn[aria-expanded="true"] { box-shadow: inset 0 0 0 1.5px var(--mdd-mapper-accent); }
.mdd-mapper[data-done] .mdd-mapper-s { cursor: default; }
.mdd-mapper-d[data-linked] > .mdd-mapper-port { background: oklch(0.8 0.12 var(--mdd-mapper-h)); box-shadow: inset 0 0 0 2px oklch(0.8 0.12 var(--mdd-mapper-h)); }
.mdd-mapper-d[data-req]:not([data-linked]) .mdd-mapper-dbtn { box-shadow: inset 0 0 0 1px oklch(0.84 0.12 75 / 0.45); }
.mdd-mapper-val[data-in] { animation: mdd-mapper-in .5s var(--mdd-mapper-out); }
@keyframes mdd-mapper-in { from { opacity: 0; translate: -10px 0; filter: blur(3px); } }
.mdd-mapper-unlink {
  grid-column: 2;
  grid-row: 1;
  z-index: 1;
  display: grid;
  place-items: center;
  inline-size: 22px;
  block-size: 22px;
  margin-inline-end: 7px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: var(--mdd-mapper-bg);
  color: var(--mdd-mapper-muted);
  cursor: pointer;
  opacity: 0;
  pointer-events: none;
  transition: opacity .2s, color .2s;
  & svg { inline-size: 12px; block-size: 12px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; }
  &:hover { color: var(--mdd-mapper-danger); }
  .mdd-mapper-d[data-linked]:is(:hover, :focus-within) & { opacity: 1; pointer-events: auto; }
}

/* connecting: compatible targets invite, the rest step back */
.mdd-mapper[data-connecting] {
  & .mdd-mapper-d[data-ok] > .mdd-mapper-port { scale: 1.35; box-shadow: inset 0 0 0 2px var(--mdd-mapper-accent), 0 0 0 4px color-mix(in oklch, var(--mdd-mapper-accent) 22%, transparent); animation: mdd-mapper-pulse 1.1s var(--mdd-mapper-out) infinite; }
  & .mdd-mapper-d[data-bad] .mdd-mapper-dbtn { opacity: 0.45; }
  & .mdd-mapper-d[data-hot][data-ok] .mdd-mapper-dbtn { box-shadow: inset 0 0 0 1.5px var(--mdd-mapper-accent); background: color-mix(in oklch, var(--mdd-mapper-accent) 12%, var(--mdd-mapper-panel)); scale: 1.02; }
  & .mdd-mapper-d[data-hot][data-bad] .mdd-mapper-dbtn { opacity: 1; box-shadow: inset 0 0 0 1.5px var(--mdd-mapper-danger); background: color-mix(in oklch, var(--mdd-mapper-danger) 10%, var(--mdd-mapper-panel)); }
  & .mdd-mapper-d[data-hot][data-bad] .mdd-mapper-val { color: var(--mdd-mapper-danger); }
  & .mdd-mapper-dbtn[tabindex="0"]:focus-visible { outline-offset: 2px; }
  & .mdd-mapper-s:not([data-source]) { opacity: 0.55; }
}
@keyframes mdd-mapper-pulse { 50% { box-shadow: inset 0 0 0 2px var(--mdd-mapper-accent), 0 0 0 7px color-mix(in oklch, var(--mdd-mapper-accent) 0%, transparent); } }
.mdd-mapper-d[data-shake] .mdd-mapper-dbtn { animation: mdd-mapper-shake .42s cubic-bezier(.36,.07,.19,.97); }
@keyframes mdd-mapper-shake { 20%, 60% { translate: -4px 0; } 40%, 80% { translate: 4px 0; } }

/* wires */
.mdd-mapper-wires {
  position: absolute;
  inset: 0;
  inline-size: 100%;
  block-size: 100%;
  overflow: visible;
  pointer-events: none;
  z-index: 1;
  & path { fill: none; stroke-linecap: round; }
}
.mdd-mapper-wire {
  stroke: oklch(0.8 0.12 var(--mdd-mapper-h));
  stroke-width: 2;
  filter: drop-shadow(0 0 4px oklch(0.8 0.12 var(--mdd-mapper-h) / 0.45));
  transition: stroke-width .2s, opacity .3s;
  &[data-dim] { opacity: 0.25; }
  &[data-hot] { stroke-width: 3; }
}
.mdd-mapper-hit { stroke: transparent; stroke-width: 14; pointer-events: stroke; cursor: pointer; }
.mdd-mapper-live {
  stroke: var(--mdd-mapper-accent);
  stroke-width: 2;
  stroke-dasharray: 5 5;
  opacity: 0;
  animation: mdd-mapper-flow .5s linear infinite;
  [data-connecting] & { opacity: 1; }
  &[data-snap="ok"] { stroke: oklch(0.8 0.12 var(--mdd-mapper-h)); stroke-dasharray: none; stroke-width: 2.5; }
  &[data-snap="bad"] { stroke: var(--mdd-mapper-danger); }
}
@keyframes mdd-mapper-flow { to { stroke-dashoffset: -10; } }
.mdd-mapper-packets { position: absolute; inset: 0; pointer-events: none; z-index: 2; }
.mdd-mapper-packet {
  position: absolute;
  inset: 0 auto auto 0;
  inline-size: 8px;
  block-size: 8px;
  border-radius: 50%;
  background: oklch(0.95 0.06 var(--mdd-mapper-h));
  box-shadow: 0 0 0 3px oklch(0.8 0.12 var(--mdd-mapper-h) / 0.35), 0 0 12px oklch(0.85 0.12 var(--mdd-mapper-h));
  offset-rotate: 0deg;
}

/* column chooser: sits over the CSV side, pointing at its field */
.mdd-mapper-menu {
  position: absolute;
  z-index: 5;
  display: grid;
  gap: 2px;
  padding: 6px;
  border-radius: 12px;
  background: color-mix(in oklch, var(--mdd-mapper-ink) 4%, var(--mdd-mapper-panel));
  box-shadow: 0 0 0 1px color-mix(in oklch, var(--mdd-mapper-ink) 16%, transparent), 0 18px 40px -12px oklch(0 0 0 / 0.75);
  transform-origin: right var(--mdd-mapper-notch, 50%);
  animation: mdd-mapper-pop .22s var(--mdd-mapper-out);
  &[hidden] { display: none; }
  &::after {
    content: "";
    position: absolute;
    inset-inline-end: -5px;
    inset-block-start: var(--mdd-mapper-notch, 50%);
    inline-size: 10px;
    block-size: 10px;
    margin-block-start: -5px;
    background: inherit;
    box-shadow: 1px -1px 0 0 color-mix(in oklch, var(--mdd-mapper-ink) 16%, transparent);
    rotate: 45deg;
  }
}
@keyframes mdd-mapper-pop { from { opacity: 0; translate: 6px 0; scale: .97; } }
.mdd-mapper-menu-head {
  padding: 3px 6px 5px;
  font-size: 10.5px;
  font-weight: 650;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--mdd-mapper-faint);
  text-wrap: balance;
  & b { color: var(--mdd-mapper-ink); font-weight: 650; }
}
.mdd-mapper-opt {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  grid-template-areas: "g name ck" "g sub ck";
  align-items: center;
  column-gap: 8px;
  inline-size: 100%;
  block-size: 34px;
  padding: 0 8px 0 5px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  text-align: start;
  cursor: pointer;
  transition: background-color .15s;
  & .mdd-mapper-glyph { grid-area: g; inline-size: 20px; block-size: 20px; }
  & .mdd-mapper-name { font-size: 12px; }
  &:hover, &:focus-visible { background: color-mix(in oklch, var(--mdd-mapper-ink) 8%, transparent); }
  &:focus-visible { outline-offset: -2px; }
  &[aria-checked="true"] { background: color-mix(in oklch, oklch(0.8 0.12 var(--mdd-mapper-h)) 12%, transparent); }
  &[aria-checked="true"]::after {
    content: "";
    grid-area: ck;
    inline-size: 9px;
    block-size: 5px;
    margin: 0 2px 3px 0;
    border: solid var(--mdd-mapper-accent);
    border-width: 0 0 2px 2px;
    rotate: -45deg;
  }
  &[aria-disabled="true"] { cursor: not-allowed; }
  &[aria-disabled="true"] > :not(.mdd-mapper-sample) { opacity: 0.45; }
  &[aria-disabled="true"] .mdd-mapper-sample { color: color-mix(in oklch, var(--mdd-mapper-danger) 70%, var(--mdd-mapper-muted)); }
  &[data-act="unmap"] { margin-block-start: 3px; }
  &[data-act="unmap"]::before { content: ""; position: absolute; inset: -3px 4px auto; block-size: 1px; background: var(--mdd-mapper-line); }
  &[data-act="unmap"] .mdd-mapper-glyph { background: color-mix(in oklch, var(--mdd-mapper-danger) 14%, transparent); color: var(--mdd-mapper-danger); }
  &[data-shake] { animation: mdd-mapper-shake .42s cubic-bezier(.36,.07,.19,.97); }
}
.mdd-mapper-menu-note {
  padding: 6px 6px 3px;
  font-size: 11px;
  color: oklch(0.84 0.12 75);
  text-wrap: pretty;
}

/* ---------- footer ---------- */
.mdd-mapper-foot {
  grid-area: foot;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding-block-start: 12px;
  border-block-start: 1px solid var(--mdd-mapper-line);
}
.mdd-mapper-msg {
  font-size: 11.5px;
  color: var(--mdd-mapper-muted);
  text-wrap: pretty;
  &[data-tone="bad"] { color: var(--mdd-mapper-danger); }
  &[data-tone="ok"] { color: var(--mdd-mapper-accent); }
}
.mdd-mapper-actions { display: flex; gap: 6px; }
.mdd-mapper-auto, .mdd-mapper-import {
  position: relative;
  block-size: 32px;
  padding: 0 12px;
  border: 0;
  border-radius: 9px;
  font-size: 12px;
  font-weight: 650;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color .2s, color .2s, scale .2s var(--mdd-mapper-out), opacity .2s;
  &:active:not(:disabled) { scale: 0.96; }
}
.mdd-mapper-auto {
  background: transparent;
  box-shadow: inset 0 0 0 1px var(--mdd-mapper-line);
  color: var(--mdd-mapper-ink);
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--mdd-mapper-ink) 6%, transparent); }
  &:disabled { opacity: 0.4; cursor: default; }
}
.mdd-mapper-import {
  overflow: hidden;
  background: linear-gradient(90deg, color-mix(in oklch, var(--mdd-mapper-accent) 70%, white) var(--mdd-mapper-p), var(--mdd-mapper-accent) 0);
  color: oklch(0.2 0.04 165);
  &:disabled { background: color-mix(in oklch, var(--mdd-mapper-ink) 9%, transparent); color: var(--mdd-mapper-faint); cursor: not-allowed; }
  &[data-busy] { cursor: progress; }
  &[data-done], &[data-done]:disabled {
    cursor: default;
    background: color-mix(in oklch, var(--mdd-mapper-accent) 16%, transparent);
    color: var(--mdd-mapper-accent);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--mdd-mapper-accent) 45%, transparent);
  }
  &[data-done] span::before { content: ""; display: inline-block; inline-size: 9px; block-size: 5px; margin: 0 7px 3px 1px; border: solid currentColor; border-width: 0 0 2px 2px; rotate: -45deg; }
}

.mdd-mapper-sr {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

@container (width < 340px) {
  .mdd-mapper-glyph { display: none; }
  .mdd-mapper-s, .mdd-mapper-dbtn { grid-template-columns: minmax(0, 1fr); grid-template-areas: "name" "sub"; padding-inline: 9px; }
  .mdd-mapper-foot { grid-template-columns: 1fr; }
  .mdd-mapper-actions { justify-content: end; }
}

@media (prefers-reduced-motion: reduce) {
  .mdd-mapper-live { animation: none; }
  .mdd-mapper[data-connecting] .mdd-mapper-d[data-ok] > .mdd-mapper-port { animation: none; scale: 1; }
  .mdd-mapper-val[data-in], .mdd-mapper-d[data-shake] .mdd-mapper-dbtn { animation: none; }
  .mdd-mapper-s, .mdd-mapper-dbtn, .mdd-mapper-port { transition: box-shadow .2s, background-color .2s, opacity .2s; }
  .mdd-mapper-packet { display: none; }
  .mdd-mapper-menu, .mdd-mapper-opt[data-shake] { animation: none; }
}

