const ROWS = 248;
const SRC = [
  { id: "full", t: "Full name", v: "Ada Okafor", type: "text" },
  { id: "mail", t: "E-mail", v: "ada@kestrelworks.co", type: "email" },
  { id: "co", t: "Company", v: "Kestrel Works", type: "text" },
  { id: "tel", t: "Phone #", v: "+44 20 7946 0321", type: "phone" },
  { id: "signup", t: "Signed up", v: "2026-03-14", type: "date" },
  { id: "plan", t: "Plan", v: "Team", type: "text" },
  { id: "seats", t: "Seats", v: "12", type: "number" }
];
const DST = [
  { id: "name", t: "Name", type: "text", req: true },
  { id: "email", t: "Email", type: "email", req: true },
  { id: "org", t: "Organization", type: "text" },
  { id: "phone", t: "Phone", type: "phone" },
  { id: "created", t: "Created at", type: "date" },
  { id: "seatcount", t: "Seat count", type: "number" },
  { id: "stage", t: "Lifecycle stage", type: "enum" }
];
const INITIAL = { name: "full", org: "co" };
const AUTO = { name: "full", email: "mail", org: "co", phone: "tel", created: "signup", seatcount: "seats" };
const HUE = { text: 80, email: 32, phone: 165, date: 250, number: 118, enum: 330 };
const ICON = {
  text: '<path d="M4 4.5h8M8 4.5v8"/>',
  email: '<rect x="2.5" y="4" width="11" height="8.5" rx="1.5"/><path d="M3 5l5 4 5-4"/>',
  phone: '<rect x="5" y="2" width="6" height="12" rx="1.5"/><path d="M7.4 11.5h1.2"/>',
  date: '<rect x="2.5" y="3.5" width="11" height="10" rx="1.5"/><path d="M2.5 6.5h11M5.5 2v3M10.5 2v3"/>',
  number: '<path d="M6.5 2.5l-1.5 11M11 2.5l-1.5 11M3 6h10M2.5 10h10"/>',
  enum: '<path d="M3 4.5h.5M6 4.5h7M3 8h.5M6 8h7M3 11.5h.5M6 11.5h7"/>'
};
const glyph = (type) => '<span class="mdd-mapper-glyph" data-type="' + type + '" aria-hidden="true"><svg viewBox="0 0 16 16">' + ICON[type] + "</svg></span>";
const S = Object.fromEntries(SRC.map((s) => [s.id, s]));
const D = Object.fromEntries(DST.map((d) => [d.id, d]));
const $ = (q) => root.querySelector(q);
const board = $(".mdd-mapper-board");
const srcList = $(".mdd-mapper-src");
const dstList = $(".mdd-mapper-dst");
const wiresG = $("[data-wires]");
const liveWire = $(".mdd-mapper-live");
const packets = $(".mdd-mapper-packets");
const msg = $("[data-msg]");
const countEl = $("[data-count]");
const reqEl = $("[data-req]");
const meter = $(".mdd-mapper-meter");
const autoBtn = $(".mdd-mapper-auto");
const importBtn = $(".mdd-mapper-import");
const menu = $(".mdd-mapper-menu");
const live = $(".mdd-mapper-sr");
const reduce = () => matchMedia("(prefers-reduced-motion: reduce)").matches;
const say = (m) => { live.textContent = ""; requestAnimationFrame(() => { if (!root.isConnected) return; live.textContent = m; }); };
const NS = "http://www.w3.org/2000/svg";
const MSG0 = msg.textContent;

let map = { ...INITIAL };
let conn = null;
let done = false;
let busy = false;
let menuFor = null;          /* field whose column chooser is open */
let swallow = null;
let fieldTab = DST[0].id;    /* the one field in the tab order (arrows move between fields) */

function reason(s, d) {
  if (d.type === "text") return "";
  if (d.type === s.type) return "";
  const what = { email: "an email address", phone: "a phone number", date: "a date", number: "a number", enum: "a lifecycle stage (Lead, Trial, Customer)" }[d.type];
  return "“" + s.v + "” isn’t " + what;
}
const NOUN = { email: "an email address", phone: "a phone number", date: "a date", number: "a number", enum: "a lifecycle stage" };

/* ---------- build ---------- */
const srcEl = {}, dstEl = {}, wires = {};
for (const s of SRC) {
  const li = document.createElement("li");
  li.innerHTML = '<button type="button" class="mdd-mapper-s" data-type="' + s.type + '">' + glyph(s.type) + '<span class="mdd-mapper-name"></span><span class="mdd-mapper-sample"></span><i class="mdd-mapper-port"></i></button>';
  const b = li.firstChild;
  b.dataset.id = s.id;
  b.querySelector(".mdd-mapper-name").textContent = s.t;
  b.querySelector(".mdd-mapper-sample").textContent = s.v;
  srcEl[s.id] = b;
  srcList.append(li);
}
for (const d of DST) {
  const li = document.createElement("li");
  li.className = "mdd-mapper-d";
  li.dataset.id = d.id;
  if (d.req) li.dataset.req = "";
  li.innerHTML = '<i class="mdd-mapper-port"></i><button type="button" class="mdd-mapper-dbtn" tabindex="-1" aria-haspopup="menu" aria-expanded="false"><span class="mdd-mapper-name"></span><span class="mdd-mapper-val"></span>' + glyph(d.type) + '</button><button type="button" class="mdd-mapper-unlink"><svg viewBox="0 0 12 12" aria-hidden="true"><path d="M3 3l6 6M9 3l-6 6"/></svg></button>';
  li.querySelector(".mdd-mapper-name").innerHTML = d.t + (d.req ? '<b aria-hidden="true">*</b>' : "");
  li.querySelector(".mdd-mapper-unlink").setAttribute("aria-label", "Unmap " + d.t);
  dstEl[d.id] = li;
  dstList.append(li);
  const m = document.createElement("li");
  meter.append(m);
}
const srcOf = (sid) => Object.keys(map).find((d) => map[d] === sid);

/* ---------- geometry ---------- */
function port(el) {
  const r = el.querySelector(".mdd-mapper-port").getBoundingClientRect();
  const b = board.getBoundingClientRect();
  return { x: r.left + r.width / 2 - b.left, y: r.top + r.height / 2 - b.top };
}
function curve(a, z) {
  const dx = Math.max(18, Math.abs(z.x - a.x) * 0.55);
  return "M" + a.x.toFixed(1) + "," + a.y.toFixed(1) + " C" + (a.x + dx).toFixed(1) + "," + a.y.toFixed(1) + " " + (z.x - dx).toFixed(1) + "," + z.y.toFixed(1) + " " + z.x.toFixed(1) + "," + z.y.toFixed(1);
}
function wireFor(did) {
  if (wires[did]) return wires[did];
  const hit = document.createElementNS(NS, "path");
  hit.setAttribute("class", "mdd-mapper-hit");
  const p = document.createElementNS(NS, "path");
  p.setAttribute("class", "mdd-mapper-wire");
  wiresG.append(hit, p);
  hit.addEventListener("pointerenter", () => hot(did, true));
  hit.addEventListener("pointerleave", () => hot(did, false));
  hit.addEventListener("click", () => { if (!done && !conn) unlink(did, true); });
  return (wires[did] = { p, hit });
}
function hot(did, on) {
  const w = wires[did];
  if (!w) return;
  w.p.toggleAttribute("data-hot", on);
  for (const k in wires) if (k !== did) wires[k].p.toggleAttribute("data-dim", on);
}
function draw() {
  for (const did in wires) {
    if (!map[did]) continue;
    const d = curve(port(srcEl[map[did]]), port(dstEl[did]));
    wires[did].p.setAttribute("d", d);
    wires[did].hit.setAttribute("d", d);
  }
}

/* ---------- state → DOM ---------- */
/* once imported, the mapping is read-only until Start over */
function locked(el) {
  if (done) { el.setAttribute("aria-disabled", "true"); el.title = "Imported — choose Start over to change the mapping"; }
  else { el.removeAttribute("aria-disabled"); el.removeAttribute("title"); }
}
function paint() {
  for (const s of SRC) {
    const b = srcEl[s.id];
    const to = srcOf(s.id);
    b.toggleAttribute("data-linked", !!to);
    b.setAttribute("aria-label", s.t + ", sample " + s.v + (to ? ", mapped to " + D[to].t : ", not mapped") + ". Press Enter to map.");
    locked(b);
  }
  DST.forEach((d, i) => {
    const li = dstEl[d.id];
    const sid = map[d.id];
    li.toggleAttribute("data-linked", !!sid);
    li.toggleAttribute("data-skip", !sid && !d.req);
    if (sid) li.style.setProperty("--mdd-mapper-link-h", HUE[S[sid].type]);
    const val = li.querySelector(".mdd-mapper-val");
    const txt = sid ? S[sid].v : d.req ? "Required" : "Skip";
    if (val.textContent !== txt) {
      val.textContent = txt;
      if (sid) { val.removeAttribute("data-in"); val.offsetWidth; val.setAttribute("data-in", ""); }
    }
    li.querySelector(".mdd-mapper-unlink").hidden = !sid || done;
    li.querySelector(".mdd-mapper-dbtn").setAttribute("aria-label", d.t + (d.req ? ", required" : "") + ", " + (sid ? "mapped from " + S[sid].t : "not mapped"));
    locked(li.querySelector(".mdd-mapper-dbtn"));
    const m = meter.children[i];
    m.toggleAttribute("data-on", !!sid);
    if (sid) m.dataset.type = S[sid].type; else delete m.dataset.type;
  });
  const n = Object.keys(map).length;
  countEl.textContent = n + " of " + DST.length + " mapped";
  const missing = DST.filter((d) => d.req && !map[d.id]).map((d) => d.t);
  reqEl.toggleAttribute("data-ok", !missing.length);
  reqEl.textContent = missing.length ? missing.join(" and ") + (missing.length > 1 ? " are" : " is") + " required" : "Required fields mapped";
  if (!busy && !done) {
    importBtn.disabled = missing.length > 0;
    importBtn.querySelector("span").textContent = missing.length ? "Import" : "Import " + ROWS;
  }
  autoBtn.disabled = !done && !Object.entries(AUTO).some(([d, s]) => map[d] !== s && !srcOf(s) && !map[d]);
}

/* ---------- link / unlink ---------- */
function animateIn(did) {
  const w = wireFor(did);
  draw();
  if (reduce()) return;
  const len = w.p.getTotalLength();
  w.p.animate([{ strokeDasharray: len + " " + len, strokeDashoffset: len }, { strokeDasharray: len + " " + len, strokeDashoffset: 0 }], { duration: 420, easing: "cubic-bezier(.16,1,.3,1)" });
  const dot = document.createElement("i");
  dot.className = "mdd-mapper-packet";
  dot.dataset.type = S[map[did]].type;
  dot.style.offsetPath = 'path("' + w.p.getAttribute("d") + '")';
  packets.append(dot);
  dot.animate([{ offsetDistance: "0%", opacity: 0 }, { opacity: 1, offset: 0.15 }, { opacity: 1, offset: 0.85 }, { offsetDistance: "100%", opacity: 0 }], { duration: 700, delay: 140, easing: "cubic-bezier(.45,0,.25,1)", fill: "both" })
    .finished.then(() => dot.remove(), () => dot.remove());
}
function dropWire(did) {
  const w = wires[did];
  if (!w) return;
  delete wires[did];
  w.hit.remove();
  if (reduce()) { w.p.remove(); return; }
  const len = w.p.getTotalLength();
  w.p.animate([{ strokeDasharray: len + " " + len, strokeDashoffset: 0, opacity: 1 }, { strokeDasharray: len + " " + len, strokeDashoffset: -len, opacity: 0.2 }], { duration: 260, easing: "cubic-bezier(.4,0,1,1)" })
    .finished.then(() => w.p.remove(), () => w.p.remove());
}
function link(sid, did) {
  const prevTarget = srcOf(sid);
  const replaced = map[did];
  if (prevTarget && prevTarget !== did) { delete map[prevTarget]; dropWire(prevTarget); }
  if (replaced && replaced !== sid) dropWire(did);
  if (map[did] === sid) return;
  map[did] = sid;
  const w = wireFor(did);
  w.p.dataset.type = S[sid].type;
  paint();
  animateIn(did);
  tone("ok", S[sid].t + " → " + D[did].t + (replaced && replaced !== sid ? " (replaced " + S[replaced].t + ")" : ""));
  say(S[sid].t + " mapped to " + D[did].t + ". " + countEl.textContent + ". " + reqEl.textContent + ".");
}
function unlink(did, announce) {
  if (!map[did]) return;
  const sid = map[did];
  delete map[did];
  dropWire(did);
  paint();
  if (announce) { tone("", S[sid].t + " unmapped from " + D[did].t + "."); say(S[sid].t + " unmapped. " + reqEl.textContent + "."); }
}
function tone(t, text) {
  if (t) msg.dataset.tone = t; else delete msg.dataset.tone;
  msg.textContent = text;
}
dstList.addEventListener("click", (e) => {
  const u = e.target.closest(".mdd-mapper-unlink");
  if (u && !done) {
    const li = u.closest(".mdd-mapper-d");
    unlink(li.dataset.id, true);
    li.querySelector(".mdd-mapper-dbtn").focus({ preventScroll: true });
    return;
  }
  /* clicking a field (with no column in hand) opens its column chooser —
     the click alternative to dragging a wire */
  const f = e.target.closest(".mdd-mapper-dbtn");
  if (!f || done) return;
  const did = f.closest(".mdd-mapper-d").dataset.id;
  if (conn) {
    if (conn.mode === "kbd") { focusTarget(did); finish(true); }
    return;                                   /* click mode is finished by the root handler */
  }
  rove(did);
  if (swallow === did && e.detail) { swallow = null; return; }
  if (menuFor === did) closeMenu(true); else openMenu(did);
});
dstList.addEventListener("pointerover", (e) => { const li = e.target.closest(".mdd-mapper-d"); if (li && !conn) hot(li.dataset.id, true); });
dstList.addEventListener("pointerout", (e) => { const li = e.target.closest(".mdd-mapper-d"); if (li && !conn && !li.contains(e.relatedTarget)) hot(li.dataset.id, false); });

/* ---------- connecting (pointer drag, click-click, or keyboard) ---------- */
function begin(sid, mode) {
  closeMenu(false);
  conn = { sid, mode, hot: null, x: 0, y: 0 };
  root.setAttribute("data-connecting", "");
  srcEl[sid].setAttribute("data-source", "");
  for (const d of DST) {
    const bad = reason(S[sid], d);
    dstEl[d.id].toggleAttribute("data-ok", !bad);
    dstEl[d.id].toggleAttribute("data-bad", !!bad);
  }
  tone("", "Mapping " + S[sid].t + " · drop on a field" + (mode === "kbd" ? ", or press Escape" : ""));
}
function setHot(did) {
  if (conn.hot === did) return;
  if (conn.hot) dstEl[conn.hot].removeAttribute("data-hot");
  conn.hot = did;
  if (!did) { liveWire.removeAttribute("data-snap"); tone("", "Mapping " + S[conn.sid].t + " · drop on a field"); return; }
  dstEl[did].setAttribute("data-hot", "");
  const bad = reason(S[conn.sid], D[did]);
  liveWire.dataset.snap = bad ? "bad" : "ok";
  liveWire.dataset.type = S[conn.sid].type;
  tone(bad ? "bad" : "ok", bad ? D[did].t + ": " + bad : "Release to map " + S[conn.sid].t + " → " + D[did].t);
  if (conn.mode === "kbd") say(D[did].t + (bad ? ". Can’t map: " + bad : ". Press Enter to map."));
}
function aim() {
  const a = port(srcEl[conn.sid]);
  const z = conn.hot ? port(dstEl[conn.hot]) : { x: conn.x, y: conn.y };
  liveWire.setAttribute("d", curve(a, z));
}
function pick(x, y) {
  const b = board.getBoundingClientRect();
  conn.x = x - b.left;
  conn.y = y - b.top;
  let best = null, bd = 34;
  for (const d of DST) {
    const r = dstEl[d.id].getBoundingClientRect();
    const inside = x >= r.left - 18 && x <= r.right && y >= r.top && y <= r.bottom;
    const p = port(dstEl[d.id]);
    const dist = inside ? 0 : Math.hypot(conn.x - p.x, conn.y - p.y);
    if (dist < bd) { bd = dist; best = d.id; }
  }
  setHot(best);
  aim();
}
function finish(commit) {
  const c = conn;
  if (!c) return;
  conn = null;
  root.removeAttribute("data-connecting");
  srcEl[c.sid].removeAttribute("data-source");
  for (const d of DST) { const li = dstEl[d.id]; li.removeAttribute("data-ok"); li.removeAttribute("data-bad"); li.removeAttribute("data-hot"); }
  rove(fieldTab);
  liveWire.removeAttribute("data-snap");
  const target = commit ? c.hot : null;
  const bad = target ? reason(S[c.sid], D[target]) : "";
  if (target && !bad) link(c.sid, target);
  else {
    if (target && bad) {
      const li = dstEl[target];
      li.removeAttribute("data-shake"); li.offsetWidth; li.setAttribute("data-shake", "");
      setTimeout(() => li.removeAttribute("data-shake"), 450);
      tone("bad", "Can’t map " + S[c.sid].t + " to " + D[target].t + ": " + bad + ".");
      say("Can’t map. " + bad + ".");
    } else { tone("", MSG0); if (c.mode !== "pointer") say("Cancelled."); }
    if (!reduce() && liveWire.getAttribute("d")) {
      const len = liveWire.getTotalLength();
      liveWire.style.opacity = "1";
      liveWire.animate([{ strokeDasharray: len + " " + len, strokeDashoffset: 0 }, { strokeDasharray: len + " " + len, strokeDashoffset: len }], { duration: 240, easing: "cubic-bezier(.4,0,1,1)" })
        .finished.then(() => { liveWire.style.opacity = ""; liveWire.setAttribute("d", ""); }, () => {});
      return void (c.mode === "kbd" && srcEl[c.sid].focus());
    }
  }
  liveWire.setAttribute("d", "");
  if (c.mode === "kbd") srcEl[c.sid].focus();
}

srcList.addEventListener("pointerdown", (e) => {
  const b = e.target.closest(".mdd-mapper-s");
  if (!b || e.button !== 0 || done) return;
  if (conn) { finish(false); return; }
  e.preventDefault();
  b.setPointerCapture(e.pointerId);
  const x0 = e.clientX, y0 = e.clientY;
  begin(b.dataset.id, "pointer");
  pick(e.clientX, e.clientY);
  let moved = false;
  const move = (ev) => { if (Math.hypot(ev.clientX - x0, ev.clientY - y0) > 5) moved = true; if (conn) pick(ev.clientX, ev.clientY); };
  const up = (ev) => {
    b.removeEventListener("pointermove", move);
    b.removeEventListener("pointerup", up);
    b.removeEventListener("pointercancel", up);
    if (!conn) return;
    if (!moved && ev.type === "pointerup") { conn.mode = "click"; tone("", "Now click a field for " + S[conn.sid].t + ", or press Escape"); return; }
    finish(ev.type === "pointerup");
  };
  b.addEventListener("pointermove", move);
  b.addEventListener("pointerup", up);
  b.addEventListener("pointercancel", up);
});
root.addEventListener("pointermove", (e) => { if (conn && conn.mode === "click") pick(e.clientX, e.clientY); });
root.addEventListener("click", (e) => {
  if (!conn || conn.mode !== "click") return;
  if (e.target.closest(".mdd-mapper-s")) return;
  pick(e.clientX, e.clientY);
  finish(!!conn.hot);
});

/* keyboard: Enter on a column, arrows through fields, Enter to map */
srcList.addEventListener("keydown", (e) => {
  const b = e.target.closest(".mdd-mapper-s");
  if (!b) return;
  const i = SRC.findIndex((s) => s.id === b.dataset.id);
  if (e.key === "ArrowDown" || e.key === "ArrowUp") {
    e.preventDefault();
    const j = Math.max(0, Math.min(SRC.length - 1, i + (e.key === "ArrowDown" ? 1 : -1)));
    srcEl[SRC[j].id].focus();
  } else if ((e.key === "Enter" || e.key === " ") && !done) {
    e.preventDefault();
    begin(b.dataset.id, "kbd");
    const cur = srcOf(b.dataset.id);
    const first = cur || (DST.find((d) => !reason(S[b.dataset.id], d) && !map[d.id]) || DST.find((d) => !reason(S[b.dataset.id], d)) || DST[0]).id;
    focusTarget(first);
  } else if ((e.key === "Delete" || e.key === "Backspace") && srcOf(b.dataset.id) && !done) {
    e.preventDefault();
    unlink(srcOf(b.dataset.id), true);
  }
});
/* fields are one tab stop: the current one is tabbable, arrows move between them */
function rove(did, focus) {
  fieldTab = did;
  for (const d of DST) dstEl[d.id].querySelector(".mdd-mapper-dbtn").tabIndex = d.id === did ? 0 : -1;
  if (focus) dstEl[did].querySelector(".mdd-mapper-dbtn").focus();
}
function focusTarget(did) {
  rove(did, true);
  setHot(did);
  aim();
}
dstList.addEventListener("keydown", (e) => {
  const li = e.target.closest(".mdd-mapper-d");
  if (!li) return;
  const i = DST.findIndex((d) => d.id === li.dataset.id);
  const step = e.key === "ArrowDown" || e.key === "ArrowUp" ? DST[(i + (e.key === "ArrowDown" ? 1 : DST.length - 1)) % DST.length].id
    : e.key === "Home" || e.key === "End" ? DST[e.key === "Home" ? 0 : DST.length - 1].id : null;
  if (conn && conn.mode === "kbd") {
    if (step) { e.preventDefault(); focusTarget(step); }
    else if (e.key === "Enter" || e.key === " ") { e.preventDefault(); finish(true); }
    else if (e.key === "Tab") { e.preventDefault(); }
  } else if (step && e.target.closest(".mdd-mapper-dbtn")) { e.preventDefault(); rove(step, true); }
  else if ((e.key === "Delete" || e.key === "Backspace") && map[li.dataset.id] && !done) { e.preventDefault(); unlink(li.dataset.id, true); }
});
root.addEventListener("keydown", (e) => {
  if (e.key !== "Escape") return;
  if (conn) { e.preventDefault(); finish(false); }
  else if (menuFor) { e.preventDefault(); closeMenu(true); }
});

/* ---------- column chooser (click or Enter on a field) ---------- */
function openMenu(did) {
  closeMenu(false);
  const d = D[did], cur = map[did];
  menuFor = did;
  dstEl[did].querySelector(".mdd-mapper-dbtn").setAttribute("aria-expanded", "true");
  menu.setAttribute("aria-label", "Column for " + d.t);
  const head = document.createElement("p");
  head.className = "mdd-mapper-menu-head";
  head.setAttribute("aria-hidden", "true");
  head.innerHTML = "Column for <b></b>";
  head.lastChild.textContent = d.t;
  menu.append(head);
  let fits = 0;
  for (const s of SRC) {
    const bad = reason(s, d);
    const other = srcOf(s.id);
    const o = document.createElement("button");
    o.type = "button";
    o.className = "mdd-mapper-opt";
    o.tabIndex = -1;
    o.dataset.id = s.id;
    o.dataset.type = s.type;
    o.setAttribute("role", "menuitemradio");
    o.setAttribute("aria-checked", String(cur === s.id));
    o.innerHTML = glyph(s.type) + '<span class="mdd-mapper-name"></span><span class="mdd-mapper-sample"></span>';
    o.querySelector(".mdd-mapper-name").textContent = s.t;
    o.querySelector(".mdd-mapper-sample").textContent = bad ? "Not " + NOUN[d.type] : other && other !== did ? "Moves from " + D[other].t : s.v;
    if (bad) { o.setAttribute("aria-disabled", "true"); o.title = "Can’t map: " + bad; } else fits++;
    menu.append(o);
  }
  if (!fits) {
    const note = document.createElement("p");
    note.className = "mdd-mapper-menu-note";
    note.textContent = "No column in this file holds " + NOUN[d.type] + (d.req ? "." : ", so it will be skipped.");
    menu.append(note);
    say(D[did].t + ": " + note.textContent);
  }
  if (cur) {
    const u = document.createElement("button");
    u.type = "button";
    u.className = "mdd-mapper-opt";
    u.tabIndex = -1;
    u.dataset.act = "unmap";
    u.setAttribute("role", "menuitem");
    u.innerHTML = '<span class="mdd-mapper-glyph" aria-hidden="true"><svg viewBox="0 0 16 16"><path d="M5 5l6 6M11 5l-6 6"/></svg></span><span class="mdd-mapper-name">Unmap</span><span class="mdd-mapper-sample"></span>';
    u.querySelector(".mdd-mapper-sample").textContent = d.req ? d.t + " is required" : "Skip " + d.t;
    menu.append(u);
  }
  menu.hidden = false;
  placeMenu();
  const opts = [...menu.querySelectorAll(".mdd-mapper-opt")];
  (opts.find((o) => o.getAttribute("aria-checked") === "true") || opts.find((o) => !o.hasAttribute("aria-disabled")) || opts[0]).focus({ preventScroll: true });
}
/* sits over the CSV side, beside the field it serves, kept inside the board */
function placeMenu() {
  if (!menuFor) return;
  const b = board.getBoundingClientRect();
  const r = dstEl[menuFor].getBoundingClientRect();
  const room = r.left - b.left - 10;
  const w = Math.min(b.width, 250, Math.max(150, room));
  menu.style.width = w + "px";
  const h = menu.offsetHeight;
  const cy = r.top + r.height / 2 - b.top;
  const top = Math.max(0, Math.min(b.height - h, cy - h / 2));
  menu.style.left = Math.max(0, room - w) + "px";
  menu.style.top = top + "px";
  menu.style.setProperty("--mdd-mapper-notch", Math.max(12, Math.min(h - 12, cy - top)) + "px");
}
function closeMenu(refocus) {
  if (!menuFor) return;
  const btn = dstEl[menuFor].querySelector(".mdd-mapper-dbtn");
  menuFor = null;
  btn.setAttribute("aria-expanded", "false");
  if (refocus) btn.focus({ preventScroll: true });
  menu.hidden = true;
  menu.replaceChildren();
}
menu.addEventListener("click", (e) => {
  const o = e.target.closest(".mdd-mapper-opt");
  if (!o || !menuFor) return;
  const did = menuFor;
  if (o.getAttribute("aria-disabled") === "true") {
    const s = S[o.dataset.id];
    o.removeAttribute("data-shake"); o.offsetWidth; o.setAttribute("data-shake", "");
    setTimeout(() => o.removeAttribute("data-shake"), 450);
    tone("bad", "Can’t map " + s.t + " to " + D[did].t + ": " + reason(s, D[did]) + ".");
    say("Can’t map. " + reason(s, D[did]) + ".");
    return;
  }
  closeMenu(true);
  if (o.dataset.act === "unmap") return unlink(did, true);
  if (map[did] === o.dataset.id) { tone("ok", D[did].t + " stays mapped from " + S[o.dataset.id].t + "."); return; }
  link(o.dataset.id, did);
});
menu.addEventListener("keydown", (e) => {
  const opts = [...menu.querySelectorAll(".mdd-mapper-opt")];
  const i = opts.indexOf(document.activeElement);
  let j = -1;
  if (e.key === "ArrowDown") j = (i + 1) % opts.length;
  else if (e.key === "ArrowUp") j = (i - 1 + opts.length) % opts.length;
  else if (e.key === "Home") j = 0;
  else if (e.key === "End") j = opts.length - 1;
  if (j > -1) { e.preventDefault(); opts[j].focus(); }
});
/* leaving the chooser (Tab away, click elsewhere) closes it */
menu.addEventListener("focusout", (e) => { if (menuFor && !menu.contains(e.relatedTarget)) closeMenu(false); });
root.addEventListener("pointerdown", (e) => {
  swallow = null;
  if (!menuFor || menu.contains(e.target)) return;
  /* pressing the chooser's own field closes it; that press's click must not reopen it */
  if (e.target.closest(".mdd-mapper-dbtn") === dstEl[menuFor].querySelector(".mdd-mapper-dbtn")) swallow = menuFor;
  closeMenu(false);
});
dstList.addEventListener("focusout", (e) => {
  if (conn && conn.mode === "kbd" && !dstList.contains(e.relatedTarget)) finish(false);
});

/* ---------- auto-match + import ---------- */
autoBtn.addEventListener("click", () => {
  if (done) return reset();
  const todo = Object.entries(AUTO).filter(([d, s]) => !map[d] && !srcOf(s));
  todo.forEach(([d, s], i) => setTimeout(() => { if (!root.isConnected || done) return; link(s, d); if (i === todo.length - 1) say("Auto-matched " + todo.length + " fields. " + reqEl.textContent + "."); }, reduce() ? 0 : i * 140));
});
importBtn.addEventListener("click", () => {
  if (busy || done || importBtn.disabled) return;
  closeMenu(false);
  busy = true;
  importBtn.setAttribute("data-busy", "");
  autoBtn.disabled = true;
  const label = importBtn.querySelector("span");
  const t0 = performance.now(), T = reduce() ? 300 : 1400;
  const step = (t) => {
    if (!root.isConnected) return;
    const k = Math.min(1, (t - t0) / T);
    const e = 1 - Math.pow(1 - k, 3);
    importBtn.style.setProperty("--mdd-mapper-p", (e * 100).toFixed(1) + "%");
    label.textContent = "Importing " + Math.round(e * ROWS) + " / " + ROWS;
    if (k < 1) return void requestAnimationFrame(step);
    busy = false;
    done = true;
    root.setAttribute("data-done", "");
    importBtn.removeAttribute("data-busy");
    importBtn.setAttribute("data-done", "");
    importBtn.disabled = true;
    importBtn.style.setProperty("--mdd-mapper-p", "100%");
    label.textContent = ROWS + " imported";
    autoBtn.textContent = "Start over";
    autoBtn.disabled = false;
    paint();
    tone("ok", ROWS + " contacts imported with " + Object.keys(map).length + " mapped fields.");
    say(ROWS + " contacts imported.");
  };
  requestAnimationFrame(step);
});
function reset() {
  closeMenu(false);
  done = false;
  root.removeAttribute("data-done");
  importBtn.removeAttribute("data-done");
  importBtn.style.removeProperty("--mdd-mapper-p");
  autoBtn.textContent = "Auto-match";
  for (const did of Object.keys(map)) if (map[did] !== INITIAL[did]) { delete map[did]; dropWire(did); }
  for (const [d, s] of Object.entries(INITIAL)) if (!map[d]) { map[d] = s; wireFor(d).p.dataset.type = S[s].type; animateIn(d); }
  paint();
  tone("", MSG0);
  say("Mapping reset.");
}

/* ---------- start ---------- */
for (const did of Object.keys(map)) wireFor(did).p.dataset.type = S[map[did]].type;
rove(fieldTab);
paint();
draw();
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  draw();
  if (conn) aim();
  placeMenu();
});
ro.observe(board);

css:
.mdd-schedule {
  --mdd-schedule-paper: oklch(0.978 0.007 70);
  --mdd-schedule-ink: oklch(0.26 0.02 50);
  --mdd-schedule-accent: oklch(0.63 0.2 32);
  --mdd-schedule-warn: oklch(0.72 0.15 70);
  --mdd-schedule-ppm: 1.6;
  --mdd-schedule-label: 76px;
  --mdd-schedule-lane: 52px;
  --mdd-schedule-line: color-mix(in oklch, var(--mdd-schedule-ink) 11%, transparent);
  --mdd-schedule-muted: color-mix(in oklch, var(--mdd-schedule-ink) 58%, var(--mdd-schedule-paper));
  --mdd-schedule-faint: color-mix(in oklch, var(--mdd-schedule-ink) 7%, var(--mdd-schedule-paper));
  --mdd-schedule-mono: ui-monospace, Menlo, monospace;
  --mdd-schedule-spring: linear(0, 0.046, 0.156, 0.297, 0.446, 0.588, 0.712, 0.815, 0.896, 0.957, 0.998, 1.025, 1.039, 1.045, 1.045, 1.041, 1.035, 1.029, 1.022, 1.016, 1.011, 1.006, 1.003, 1.001, 0.999, 0.998, 1);
  --mdd-schedule-snap: cubic-bezier(.2, .9, .25, 1);
  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-areas: "head" "scroll" "foot";
  gap: 12px;
  inline-size: 100%;
  max-inline-size: 560px;
  box-sizing: border-box;
  padding: 16px 0 14px;
  border-radius: 16px;
  background: var(--mdd-schedule-paper);
  color: var(--mdd-schedule-ink);
  font: 400 12.5px/1.35 system-ui, -apple-system, "Segoe UI", sans-serif;
  box-shadow: 0 0 0 1px var(--mdd-schedule-line), 0 22px 44px -26px oklch(0.3 0.04 50 / 0.45);
  -webkit-user-select: none;
  user-select: none;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(p, h3) { margin: 0; }
  & :where(button) { font: inherit; color: inherit; }
  & :focus-visible { outline: 2px solid var(--mdd-schedule-ink); outline-offset: 2px; }
}
.mdd-schedule [data-team="design"] { --mdd-schedule-h: 12; }
.mdd-schedule [data-team="eng"] { --mdd-schedule-h: 238; }
.mdd-schedule [data-team="people"] { --mdd-schedule-h: 152; }
.mdd-schedule [data-team="ops"] { --mdd-schedule-h: 75; }
.mdd-schedule [data-team="media"] { --mdd-schedule-h: 305; }

.mdd-schedule-head { grid-area: head; padding-inline: 16px; display: grid; gap: 1px; }
.mdd-schedule-eyebrow {
  font-size: 10.5px;
