const START = 480, END = 1080, STEP = 15, NOW = 700;
const ROOMS = [
  { id: "kelp", t: "Kelp", seats: 4 },
  { id: "basalt", t: "Basalt", seats: 8 },
  { id: "loft", t: "Loft", seats: 16 },
  { id: "booth", t: "Booth 3", seats: 2 }
];
const BK = [
  { id: "crit", t: "Design crit", room: "kelp", s: 540, e: 600, n: 4, team: "design", host: "Mara Lindqvist" },
  { id: "oneone", t: "1:1 Mara · Theo", room: "kelp", s: 810, e: 840, n: 2, team: "people", host: "Mara Lindqvist" },
  { id: "review", t: "Sprint review", room: "basalt", s: 600, e: 690, n: 8, team: "eng", host: "Ines Duarte" },
  { id: "vendor", t: "Vendor call", room: "basalt", s: 900, e: 945, n: 3, team: "ops", host: "Kwame Osei" },
  { id: "allhands", t: "All-hands", room: "loft", s: 720, e: 780, n: 14, team: "people", host: "Ruth Abara" },
  { id: "pricing", t: "Pricing workshop", room: "loft", s: 840, e: 990, n: 10, team: "ops", host: "Kwame Osei" },
  { id: "interview", t: "Interview · R. Iyer", room: "booth", s: 660, e: 705, n: 2, team: "people", host: "Theo Marsh" },
  { id: "podcast", t: "Podcast edit", room: "booth", s: 960, e: 1050, n: 1, team: "media", host: "Jun Park" }
];
const $ = (q) => root.querySelector(q);
const scroller = $(".mdd-schedule-scroll");
const grid = $(".mdd-schedule-grid");
const hours = $(".mdd-schedule-hours");
const nowLine = $(".mdd-schedule-now");
const detail = $(".mdd-schedule-detail");
const help = $(".mdd-schedule-help");
const live = $(".mdd-schedule-sr");
const reduce = () => matchMedia("(prefers-reduced-motion: reduce)").matches;
const say = (m) => { live.textContent = ""; requestAnimationFrame(() => { if (!root.isConnected) return; live.textContent = m; }); };
const R = Object.fromEntries(ROOMS.map((r) => [r.id, r]));
const B = Object.fromEntries(BK.map((b) => [b.id, { ...b }]));
const clock = (m) => Math.floor(m / 60) + ":" + String(m % 60).padStart(2, "0");
const span = (b) => clock(b.s) + "–" + clock(b.e);
const ppm = () => parseFloat(getComputedStyle(grid).getPropertyValue("--mdd-schedule-ppm")) || 1.6;
let selected = null;
let drag = null;

/* ---------- build ---------- */
for (let h = 8; h <= 18; h++) {
  const s = document.createElement("span");
  s.style.setProperty("--m", (h - 8) * 60);
  s.textContent = h + ":00";
  if (h < 18) hours.append(s);
}
nowLine.style.setProperty("--m", NOW - START);
const lanes = {}, labels = {}, els = {};
for (const r of ROOMS) {
  const lab = document.createElement("div");
  lab.className = "mdd-schedule-room";
  lab.innerHTML = "<b></b><small></small>";
  lab.querySelector("b").textContent = r.t;
  lab.querySelector("small").textContent = r.seats + " seats";
  const lane = document.createElement("div");
  lane.className = "mdd-schedule-lane";
  lane.dataset.room = r.id;
  lane.setAttribute("role", "group");
  lane.setAttribute("aria-label", r.t + ", " + r.seats + " seats");
