  labels[r.id] = lab;
}
for (const b of Object.values(B)) {
  const el = document.createElement("button");
  el.type = "button";
  el.className = "mdd-schedule-block";
  el.dataset.id = b.id;
  el.dataset.team = b.team;
  el.setAttribute("aria-pressed", "false");
  el.setAttribute("aria-roledescription", "booking");
  el.innerHTML = '<span class="mdd-schedule-name"></span><span class="mdd-schedule-time"></span><span class="mdd-schedule-warn" aria-hidden="true">!</span><span class="mdd-schedule-edge" data-edge="start" aria-hidden="true"></span><span class="mdd-schedule-edge" data-edge="end" aria-hidden="true"></span>';
  el.querySelector(".mdd-schedule-name").textContent = b.t;
  els[b.id] = el;
}

/* ---------- model ---------- */
function clash(id, room, s, e) {
  return Object.values(B).find((o) => o.id !== id && o.room === room && s < o.e && e > o.s) || null;
}
function over(b, room) { return b.n > R[room].seats; }
function place(b) {
  const el = els[b.id];
  el.style.setProperty("--s", b.s);
  el.style.setProperty("--d", b.e - b.s);
  el.querySelector(".mdd-schedule-time").textContent = span(b);
  el.toggleAttribute("data-warn", over(b, b.room));
  el.setAttribute("aria-label", b.t + ", " + R[b.room].t + ", " + span(b) + ", " + b.n + " people" + (over(b, b.room) ? ", over room capacity" : ""));
