  if (el.parentNode !== lane) {
    const f = document.activeElement === el;
    if (lane.moveBefore && el.parentNode) lane.moveBefore(el, null); else lane.append(el);
    if (f && document.activeElement !== el) el.focus({ preventScroll: true });
  }
  const kids = [...lane.children].sort((x, y) => B[x.dataset.id].s - B[y.dataset.id].s);
  kids.forEach((k, i) => { if (lane.children[i] !== k) (lane.moveBefore ? lane.moveBefore(k, lane.children[i]) : lane.insertBefore(k, lane.children[i])); });
}
