  const all = Object.values(B);
  const mins = all.reduce((s, b) => s + (b.e - b.s), 0);
  const cap = ROOMS.length * (END - START);
  const free = ROOMS.filter((r) => !all.some((b) => b.room === r.id && b.s <= NOW && b.e > NOW)).length;
  $("[data-booked]").textContent = String(Math.round((mins / 60) * 100) / 100) + " h booked";
  $("[data-util]").textContent = Math.round((mins / cap) * 100) + "% of capacity";
  $("[data-free]").textContent = free + " of " + ROOMS.length + " rooms free now";
}
function card() {
  const prev = detail.querySelector(".mdd-schedule-card");
  if (!selected) {
    if (prev) prev.remove();
    help.hidden = false;
    return;
  }
  const b = B[selected];
  help.hidden = true;
  const c = prev || document.createElement("div");
  c.className = "mdd-schedule-card";
  c.dataset.team = b.team;
  c.innerHTML = '<i aria-hidden="true"></i><b></b><p></p><button type="button" aria-label="Clear selection"><svg viewBox="0 0 12 12" aria-hidden="true"><path d="M3 3l6 6M9 3l-6 6"/></svg></button>';
  c.querySelector("b").textContent = b.t;
  const p = c.querySelector("p");
  p.textContent = over(b, b.room)
    ? R[b.room].t + " · " + span(b) + " · " + b.n + " people, room seats " + R[b.room].seats
    : R[b.room].t + " · " + span(b) + " · " + b.n + " people · " + b.host;
  p.toggleAttribute("data-warn", over(b, b.room));
  if (!prev) detail.append(c);
}
function select(id) {
  if (selected && els[selected]) els[selected].setAttribute("aria-pressed", "false");
  selected = id;
  if (id) els[id].setAttribute("aria-pressed", "true");
  card();
}
detail.addEventListener("click", (e) => {
  if (e.target.closest(".mdd-schedule-card button")) { const id = selected; select(null); if (id) els[id].focus({ preventScroll: true }); }
});

/* ---------- pointer: move or resize, snapped to 15 minutes ---------- */
function laneAt(y) {
  for (const r of ROOMS) {
    const rr = lanes[r.id].getBoundingClientRect();
    if (y >= rr.top && y < rr.bottom) return r.id;
  }
  const first = lanes[ROOMS[0].id].getBoundingClientRect();
  return y < first.top ? ROOMS[0].id : ROOMS[ROOMS.length - 1].id;
}
function preview() {
  const d = drag, b = B[d.id], el = els[d.id];
  const k = ppm();
  const dm = Math.round((d.cx - d.x0 + scroller.scrollLeft - d.sl0) / k / STEP) * STEP;
  const len = d.e0 - d.s0;
  let s = d.s0, e = d.e0, room = b.room;
  if (d.mode === "move") {
    s = Math.max(START, Math.min(END - len, d.s0 + dm));
    e = s + len;
    room = laneAt(d.cy);
  } else if (d.mode === "start") s = Math.max(START, Math.min(d.e0 - STEP, d.s0 + dm));
  else e = Math.min(END, Math.max(d.s0 + STEP, d.e0 + dm));
  if (s === d.s && e === d.e && room === d.room) return;
  d.s = s; d.e = e; d.room = room;
  el.style.setProperty("--s", s);
  el.style.setProperty("--d", e - s);
  el.style.setProperty("--dy", lanes[room].offsetTop - lanes[b.room].offsetTop + "px");
  const hit = clash(b.id, room, s, e);
  d.hit = hit;
  el.toggleAttribute("data-conflict", !!hit);
  el.toggleAttribute("data-warn", !hit && b.n > R[room].seats);
  el.querySelector(".mdd-schedule-time").textContent = hit ? "Overlaps " + hit.t : clock(s) + "–" + clock(e);
  for (const r of ROOMS) { lanes[r.id].toggleAttribute("data-target", r.id === room); labels[r.id].toggleAttribute("data-target", r.id === room); }
}
function autoScroll() {
  if (!root.isConnected) return;
  if (!drag) return;
  const r = scroller.getBoundingClientRect();
  const left = r.left + parseFloat(getComputedStyle(grid).getPropertyValue("--mdd-schedule-label"));
  let v = 0;
  if (drag.cx < left + 28) v = -Math.ceil(((left + 28 - drag.cx) / 28) * 8);
  else if (drag.cx > r.right - 28) v = Math.ceil(((drag.cx - (r.right - 28)) / 28) * 8);
  if (v) { const b0 = scroller.scrollLeft; scroller.scrollLeft = b0 + v; if (scroller.scrollLeft !== b0) preview(); }
  drag.raf = requestAnimationFrame(autoScroll);
}
function end(cancel) {
  const d = drag;
  drag = null;
  cancelAnimationFrame(d.raf || 0);
  const b = B[d.id], el = els[d.id];
  el.removeAttribute("data-dragging");
  el.removeAttribute("data-mode");
  for (const r of ROOMS) { lanes[r.id].removeAttribute("data-target"); labels[r.id].removeAttribute("data-target"); }
  const changed = d.s !== d.s0 || d.e !== d.e0 || d.room !== b.room;
  if (cancel || d.hit || !changed) {
    el.removeAttribute("data-conflict");
    el.style.setProperty("--dy", "0px");
    place(b);
    if (d.hit && !cancel) say("Can’t move " + b.t + ": it would overlap " + d.hit.t + ". Back at " + span(b) + ".");
    else if (cancel) say("Cancelled. " + b.t + " stays at " + span(b) + ".");
    return;
  }
  const from = R[b.room].t;
  b.s = d.s; b.e = d.e;
  const moved = d.room !== b.room;
  b.room = d.room;
  el.setAttribute("data-landing", "");
  el.style.setProperty("--dy", "0px");
  place(b);
  el.offsetWidth;
  el.removeAttribute("data-landing");
  stats();
  if (selected === b.id) card();
  say(b.t + (moved ? " moved from " + from + " to " + R[b.room].t : " now") + ", " + span(b) + (over(b, b.room) ? ". Warning: " + b.n + " people, room seats " + R[b.room].seats : "") + ".");
}
grid.addEventListener("pointerdown", (e) => {
  const el = e.target.closest(".mdd-schedule-block");
  if (!el || e.button !== 0 || drag) return;
  const edge = e.target.closest(".mdd-schedule-edge");
  const b = B[el.dataset.id];
  el.setPointerCapture(e.pointerId);
  const st = { started: false, x0: e.clientX, y0: e.clientY };
  const move = (ev) => {
    if (!st.started) {
      if (Math.hypot(ev.clientX - st.x0, ev.clientY - st.y0) < 4) return;
      st.started = true;
      drag = { id: b.id, mode: edge ? edge.dataset.edge : "move", x0: st.x0, sl0: scroller.scrollLeft, s0: b.s, e0: b.e, s: b.s, e: b.e, room: b.room, cx: ev.clientX, cy: ev.clientY, hit: null };
      el.setAttribute("data-dragging", "");
      el.dataset.mode = drag.mode;
      drag.raf = requestAnimationFrame(autoScroll);
    }
    if (!drag) return;
    drag.cx = ev.clientX;
    drag.cy = ev.clientY;
    preview();
  };
  const up = (ev) => {
    el.removeEventListener("pointermove", move);
    el.removeEventListener("pointerup", up);
    el.removeEventListener("pointercancel", up);
    if (st.started) { if (drag) end(ev.type !== "pointerup"); }
    else if (ev.type === "pointerup") select(selected === b.id ? null : b.id);
  };
  el.addEventListener("pointermove", move);
  el.addEventListener("pointerup", up);
  el.addEventListener("pointercancel", up);
});
root.addEventListener("keydown", (e) => { if (e.key === "Escape" && drag) { e.preventDefault(); e.stopPropagation(); end(true); } }, true);

/* ---------- keyboard ---------- */
function shake(el) {
  if (reduce()) return;
  el.removeAttribute("data-shake");
  el.offsetWidth;
  el.setAttribute("data-shake", "");
  setTimeout(() => el.removeAttribute("data-shake"), 400);
}
grid.addEventListener("keydown", (e) => {
  const el = e.target.closest(".mdd-schedule-block");
  if (!el) return;
  const b = B[el.dataset.id];
  const k = e.key;
  if (k === "Escape") {
    if (selected) { e.preventDefault(); select(null); }
    return;
  }
  if (drag) return;
  if (k === "Enter" || k === " ") { e.preventDefault(); select(selected === b.id ? null : b.id); return; }
  if (!k.startsWith("Arrow")) return;
  e.preventDefault();
  let { s, e: en, room } = b;
  const ri = ROOMS.findIndex((r) => r.id === room);
  if (e.shiftKey && (k === "ArrowLeft" || k === "ArrowRight")) en = Math.max(s + STEP, Math.min(END, en + (k === "ArrowRight" ? STEP : -STEP)));
  else if (k === "ArrowLeft" || k === "ArrowRight") { const d = k === "ArrowRight" ? STEP : -STEP; const len = en - s; s = Math.max(START, Math.min(END - len, s + d)); en = s + len; }
  else { const j = ri + (k === "ArrowDown" ? 1 : -1); if (j < 0 || j >= ROOMS.length) { shake(el); say("No room " + (k === "ArrowDown" ? "below." : "above.")); return; } room = ROOMS[j].id; }
  if (s === b.s && en === b.e && room === b.room) { shake(el); say(b.t + " is at the edge of the day."); return; }
  const hit = clash(b.id, room, s, en);
  if (hit) { shake(el); say("Can’t: " + b.t + " would overlap " + hit.t + " in " + R[room].t + "."); return; }
  const moved = room !== b.room;
  const before = el.getBoundingClientRect();
  b.s = s; b.e = en; b.room = room;
  place(b);
  if (moved && !reduce()) {
    const after = el.getBoundingClientRect();
    el.animate([{ transform: "translateY(" + (before.top - after.top) + "px)" }, { transform: "none" }], { duration: 320, easing: "cubic-bezier(.2,.9,.25,1)" });
  }
  el.focus({ preventScroll: true });
  const r = el.getBoundingClientRect(), sr = scroller.getBoundingClientRect();
  const label = parseFloat(getComputedStyle(grid).getPropertyValue("--mdd-schedule-label"));
  if (r.left < sr.left + label) scroller.scrollLeft -= sr.left + label - r.left + 12;
  else if (r.right > sr.right) scroller.scrollLeft += r.right - sr.right + 12;
  stats();
  if (selected === b.id) card();
  say(R[b.room].t + ", " + span(b) + (over(b, b.room) ? ". Warning: over capacity, room seats " + R[b.room].seats : "") + ".");
});

/* ---------- start ---------- */
for (const b of Object.values(B)) place(b);
stats();
scroller.scrollLeft = (540 - START) * ppm() - 8;
